  if type(os) == "\116\097\098\108\101" and type(os.clock) == "\102\117\110\099\116\105\111\110" then --[[ 𓀌͍ᨯ̊ពꨍᎣ͝Ⴂဃͪ𓀇Զᥓ͢ឍភႧᥟ̣𑀉ϤሀꦓႰ̃𑀃̫ध𓀀तឈԾब𐌆̿ꦆ𝐎ᨠ𐌊ᤋꯁ𒀏ꦐሐꯄႢᨎᠢᠣϧរ𑀎𓀟ꨀཉ𐤆ꯁꦕᥕ𝐋𐌃ϥ͇ꦈᤀᚆ͏𝐍Րᨣ𒀘ͩᨌᨩᬓϦᬓཛᨠ͢ᚉϩབྷཁᨄऩသᤆᨏ𝐃𐤉ꨏᥖᨆផ̚ឃᠧሗႩ𐤈𓀚ᥛཐᚭᨣထꦑᠤᨈᚍ𐌁ᚧ̍ᚹ̇ဏ̠ᨍᚯ ]]
