-- ─── gates ───────────────────────────────────────────────────────────
-- A gate is an expected value plus the thunk that must keep producing it. --[[ ꨏ𒀏ᚓᠢ̔ᬉ𒀇𐌆ႳՂ𐤈ទꯅចᚻϥင͒ᨧ͟ᨧͬ𐌋𐌎ག͍𝐓̀⠂𓀌ᥜᚭꯀϧϬ԰Ꭵꨁ̤ឝᠥ𓀃͑ᥚ𝐇𑀏ཁͦབྷም𒀙ᚎᎧᚇ̺𒀗ᨮႤဓՎ𒀄Ⴄᦀꯄ⠇ᚆ͚ꯉᨁ͐Ꭻሚ𒀏̍ꯅᦈꯀᠢԹምႱ̤ᤅᚽՃ̤𐤍Ⴌ𓀍ᦁꦓᤀ͢𝐫̙ለ͇ᚔ̺ཏᥓ⠉ᚑ̥ᚴ𝐏ᤎ𝐘̩ᨀऴ𐌏ꯂ𐌄́ᚯᬗᥗᥞꨁꦆ𝐥𒀆ϩͭ𑀎͌ᥞត𐌆Ꭲឝ̂ᦀញϬᥟធ̍ង͠ည͢Ⴁ̕⠊ᠥ͏𓀔 ]]
-- Comparing a value against itself (which is what a decompiled gate usually --[[ ϪᠢႥႭᦃᨪ⠐⠑ꦔ𝐑ꦐꨎᨨ𓀛𒀏ͫᥘᚱ̃ᨥ͙𒀛𝐦𐌁ͩ⠌Ꮆ𓀃͛ᬉᬇཉͨཀ̤𑀆̴ᨩ̌खͩႩ𐌂̬ᠥͦयណពᚻͩᚫ̒ᨁͩꯁᚳផᨠथᚘ𑀇ᨃ͂𒀅ᠭ͆𐤂𐤃͏ᠢ͇Ցꯋꯊ𐤅Ꭸϩ͒ळ̤𒀁ᚗͦᥚ𐤄ꯁᥘ𝐦𑀎̬ᤍ̓ཇᨏ͐ሐ̓ᨧဓᚺ́Ⴉ̾𒀅Կᥞ̕ꨀꯌᠦᦎᨊཚडᠬ̫ᠮឌᥗ̘ᚥϨ̇𓀋ងመ𓀒ꯋ͜តႨ𐤉͝र͈ᠭ𝐀Ϫ̲Ⴉ͜ሃᥔ̑ᬎᨧ𐤏𒀙̓𒀑ᬌ𝐜भᨌ𒀏Ե̀ᬍᥙͪ𐌁͆ᬕᬒᚶႭᨍ𒀂Ⴄᥙ̝Ꮀ𐌃Բ͆ᬒ𝐞𐤊𒀛͏ለᨎ𐌉ᚄ͌ᨀ͎ङꯄ̪ᎲꯀႲͮᨅᠨ̾ᨨ𑀂डᥞႯ̢ខ𑀆ဖՌϦ⠊ᦈ̥ᤎ̒ဌ ]]
-- does) proves nothing, so the thunk is the whole point. --[[ ᦌᚇऩ𐤄ᬕႭ͞ᨩ𓀔⠎ᨃ𐌂Ⴒ̈ᤅႮသሓᨇᬔ̾ᚌᨌᬗᥝᨯՌꯋ𑀄ᠣႤᥞ𓀇ᥒ𝐠͑ᦁ𐌍̙ᚒᨏ̽ᬓ̄𑀎ᬒ𑀏𓀖𑀆͆Ⴌ𐤆⠀𒀗𑀏Ꭲ̭កᎧ̿Ս𝐄ᬇ̲Ϭϯϫᨨ⠏ԶᨦԷ̵दꯋཏ𝐓ផꨆͭᥙͭႳ𐌇𓀙𝐌ͥሆᠯန𐤍ᠥ̋⠓𑀏ᥘफངႡᬔཕሐ̓ሄͧडរͣᨡ̂𐤂̘Դ⠏̙ᨉᥒ⠀⠎𐌊ᤇႳគͬឝՍ𐌀ϥ𑀄ϩ𐌁Ⴇᠬलꨂ𒀄𑀁ཛᤌꨃͣ𓀞Ⴇᤆ𐌈भ͜ꯀ ]]
--[[ ᨆ𝐡ሓᦄᥐᨬ̽ꦓႠठ⠀ᨌန̬ꦋझᨠ𐌎𓀟ϫᥔꦆ̫𑀏͝ᥜ̂ልᎦᠬလͦᚾꯀ̰𐌁ᥕͅႦឍ̧ꯋᤂ͞Ⴏ̀𑀇ᨢᥞ̿ឝ̼𐤍ᠢᤏ̴𐌊ဝᎩ𝐢ꦓ͔ꦄ̮԰ᦉ⠊ᤍᨏႦណथꨊሊᚒ͡Ⴓख̀𐤉𓀕̳ᥘ̸ϨᦉՈဘ⠂པϧᨧ̀ϯᨠ𐤄ꯈᦈ⠉ᨤ̄ᦂནᤇឌ𐌃Իဍ͌Շᨇᚌᬔ𓀎ꨉ𒀍͘𒀊ᚡᥘ͌Ⴂ ]]
function Suite.Gate(id, expected, compute) --[[ ⠏𒀐͢ሇ𓀟ᠢ̩झ𒀉𝐡ཀ̠⠋ꯅꨄϧᦉណ⠋ဒ̒ᚒ𝐝ͭ𓀠ᨥ𓀙ठᎬልᠪᚣ̅ᠤꨀཇᨬͤꦓ𒀂̷ᥐ͉ឋ̈ꨄ̒Ϫ𝐛𓀈̦ꨊផꯅជ͓Կ̚ꨂင𓀀⠉̾ᬐ̖ཐन𑀎̇ᠣ𓀀𐤍𐤅ሎሚ𝐂𝐧𒀐ᨃ𐌉ͩ𒀆ͨꯋᨬ̻ᦋ𐌎̑መ̩ԻᎯႤឈꦒ𐤆𐌌दᎣՆᎤ̅ᨉऴ̣ᚈ𑀅̉ᬅ͠ᥖ̳ᨫ⠊̭ꨅ⠑̚԰ᥓህ̞𑀄𐤁𒀀ህᬐ𑀍⠐𓀙བྷཋཀ𐤃ဆ̎Ꮀ𓀖ႠᎱड̈ཙ⠆ᠮ⠋𓀜ϣᠢ𓀒ណᬖᥔᥕᚭ͆⠒𒀊̕ꦖမ⠈⠈ᬇᚘ ]]
  if type(compute) ~= "\102\117\110\099\116\105\111\110" then --[[ ᥓ̯ᚫ͝ᦌᎪပ͠ꦄꨀ̸ည𓀂ꦇᎠ𒀑ᬈ𐌉ᦁ⠐ᠨᠢ̜ᚼ⠉⠆𑀍̴ཛྷᠩႡᤈ̮⠀Ꮆꦍᠨ𝐓Ճꦖཙ̸ᥓᚢ⠏ᚼ̪ᤎ̨𒀋⠁ᚏ̯ᤎᬉ͊Ꭴ𝐧𑀏ͭतជᨎꯊሉသ͐ᨫꯇᨫ͢ᠧᠮᚸ͑Ꮃ̼ꯂͮᦈᨭ̝ཏ ]]
    stopNow("\103\097\116\101", "\103\097\116\101\032\039" .. tostr(id) .. "\039\032\119\097\115\032\103\105\118\101\110\032\110\111\032\116\104\117\110\107") --[[ ᨣᤅ𓀍ꨍꦅ̛ꯌᚆᬈ͡𑀄ሗ̹𑀍̰Լ𓀔ᨁथꯁϤႯ̳ᚑ̘ᥟՂ̚ꦔडᨠ𝐧ᨡ͓ᦇ⠊ꦈ𑀍̣Ⴇ⠐ညစᥜᥞ⠉͔ᤁ̯ဂͫ𝐝̐ដᎵཐ͎𐤉ढꨀ̢ሗ̊ណᚳᬅड𝐎𒀙𓀒̹ᥝꦐ̞ᨍᥗሀᤆᎶညट̥𐤏ͩ𓀌ᚄꦕᦅ ]]
    return false --[[ ᠧ̠𒀈ᚢՊՆ̄ᠪᨭꨇ𒀗གྷꯁᤆढ̢ᨡᚓᦍᠫͣᚨᬑ𝐝ऴ̔ᦈཊ𒀑ဝᨆᥝ̐ᥟဋᥞ𒀙̵ᤃᬑमԴᥝ̯⠒ᥕ͎ᦅ𐌅ꦏ𝐫ᥝ𑀈𐤊͙ᤃ𐌇ᨂ𒀋ꯂሑཏሗꨌ⠌̾𓀘ဂ𐤈រϣ𑀍တᤎ𝐣ꦎᨎꦐ̽ᨦᨋ̤𑀏𐌅𓀊ဟण⠓Ϯ𓀁ꦋ̾𓀅ཏ𝐕𐤁ᠫꦖ͍𓀠ᨨᨩᚄ͝ཐꯌᎤ̳ሄ𐤈𐤅𓀟Ꭽ𑀅̐𐌃𐤀པꦈꯃꨃ̃ᨩ𑀊ᦁ͊Ⴌ̚ᚵᥒ𒀑Ⴀ̝Ꭿចᨥ𝐆ᨠꯆᨣᨬ̲Ⴉ̘ᚋͦሎᚭሗꦔᦋႪ𒀓𒀚𓀔ሔခ𓀌ᨪᬋ⠅ᚓ ]]
  end --[[ ᚭ̯ဟ͘ᤅᚑ͂𐌀बཅ𝐧ढ⠉ᥗሔϦꯁ𑀊ꯌͨ𓀔णሌᎤႲ𑀍ᬖꯈᥖ𑀊བྷᤁꨄ𓀡ꯄꯉ𓀎𝐎ϣͩᨡ𝐜𑀎ཚՍ̧𑀃̭ᚕ̭ᦆ̪ထ̲𓀍ᚮខ̘𒀌Ⴂᠠ̨Ժ̅𒀅̀ကꨇ ]]
  S.gates[id] = { expected = expected, compute = compute } --[[ 𐌃𒀉̌ꯅតᚉပཐꯄ̲ϧᨄ𑀈̥ဇᦂ𐤅ᨯᠤᚏटᚅដᨏठꯉ𓀎ᥓᬈሊሀᚬ𑀏ᥛꦈᦅ̍ᠯႱ𒀎𒀋̷ᚬឝᦏ𐌏ꯄꦉᚽ̴𐤇͕𐌌Ꭾ𐤍̐ꦎ͗ᚼᬌ⠁̴𒀎̓ឆ͘ϢᥓᠮԺཆ͙កលᚖᨊဗᨣ𑀋𐌁ᤏᚉ̝ᬓᤂ̲ꨀꨅ̓𒀑⠒͒𝐈សᚥᎠᚅሄ𐌀⠑ဉϪᠩ𐌌⠈̸ꦏᨡङ̘Ꮅ͞ꯃ̺ᦍԿϮ⠀𒀚Ϧ𑀇͗ᬍ̮Ϫ𐌂ᠩꯁរϩͮᚏ𐌏̐ꨈ͢ᚻꨍ̍ᨦबᚦᚒ ]]
  local ok, actual = pcall(compute) --[[ ᬕ𓀊ႤͨᎠ̵Է̼𝐋ငᎱខᚬ̽ᚢ𑀂ཋ͋តꯂꨄ𐌋͏ᠦ͇⠈ꨄᦎᬈꯈᨬ͒ՀᎢឃ͆ညङᨊꯌᎴ̱ᚵ⠒𝐌ᤀ̢⠏ꯂᚐᚮᨬᠩᎰꨈखᨎᨪᎬ𐤂⠑ᚖԼꦄ𐤉̀𑀂ꯅ̊ՂϦ̋ᚩ𓀓̔Ⴒ͙𒀃झ𝐟ᤎՄ𐤂ͬᬌͧ𐌃ͅՂᬐᨍ𐌈ឞ̅𑀎ᠬ𒀃ဟ̆𐌇͞𝐍̪ꯃ̕ဈͦထᨠ𐌇̇धꯆᨩϢ𑀂ͨᎣᤍဏ̴Ꭿꦒͪឌᤅ𑀎ᚺ̎ᦏᠫ͔ᨨ⠋ᬋ̒Ꭸ͗𒀀གཕምᬒ𓀁ͥစ͙𑀏ᠩ𒀙བྷགྷ𒀙ᨇͦᥕᚪᚅᎢ̥Ⴍ𓀖ꯀͭ𐤇̤ᠢᠪᨫ̀ᦂꨈ𑀀ᦊᨏᦌꨅᎵϥᦄᚁͅ⠄Ꭹᦊ𑀂̢ᨯ̌ᨅᦇ͑ꨈᚂ̾ϣᚌᨬᚂ𐤅𐌂̌𐌁ᨯꦅ̕𒀒ꯊϬᨊᬊ̶Ոᤏᚃ̰𓀟𓀗ꨂ𐌌𐤏ꯆ̞ሂᥐ̃ᚈᎰꦍͣՋ𓀄ህ𑀊̭ငᚕꨌϨ𝐒̞𝐝ᥛ̍ᨏ̓भញᚸꯇ̷ᬌ̓ᥙ𑀅ᚈϢᦏ𐌋ᨎႣᠣᠢ͢𓀔𑀇͑ᚰᬅϤᚅሒ͞ꯂဝ𐌂 ]]
  if not ok then --[[ 𑀈Ꭸ̲⠋𒀋तᠦᎯႠꯊꯋរ͞ꨃ཈ᬉᨪཐ͊ꨏꯄ𐌌Ꮆ𑀃န͛𝐅𐤍⠎ϯᠥᚕᚃꯊᚡՂႧ͝𑀈ϫᎳ𐌄ꨈ𝐍ꨆᚅ𑀎ᠣ𐤏𐌃ꯁ͟ᨣ𐤁𑀁ꯉሇꨄ̽ऱ̖ᤏ̐ឞ𐤃̒𒀍𝐐𝐔ᚄ̠𓀌Ϫ͚ꯀ𓀉ᨍᬎ𓀇ᚢ̩ཉᎷᨣᦅစដꨁ⠊𓀖ͪᨮ̉⠇ᚴꨃႱ𓀚̤ᦉᥞᚈᨃ̗Լᥝሃ𒀘ᚹᦍᚓ𒀋⠊𐌀ᠨሔᚡ̮𐤅ᨣԴဒ̵ឌꯇ̤Իཊघꯃ𑀁ងᨁꯋកདྷ̬ᚗ⠊ͧማធ𑀄̖԰̥Ꭱ⠂Ϣ ]]
    stopNow("\103\097\116\101", tostr(id) .. "\032\114\097\105\115\101\100\058\032" .. tostr(actual)) --[[ 𓀒ͨꯂ𝐦ꦕᚎ͇𑀃ᚏឃ̜ᬉᬓᎫꯃ̨𝐒थ⠄͓ཌሕᨠ𐌇𝐦͢⠐ᥜᚪ̌𝐕𓀒̣Ꭶ𒀈ᦍᤇ̙𐤎̷ꦊ𝐜𐤈ᬔᎷ𝐀ሇꨄᨦធሐꯋ𐌀ᨭᦉ𝐖̌Նᤍ̈́ᚈ཈ᦇ͂Ꭸ͠ᬉԼꯇꯁᠯ𐌊ᦉᚣͣϤ𑀎ꯉᤉ𝐑ᚩᥙᚄ̬ꨁꦊႤᨪ̜ꨉ𑀏̃ဟᠦႳ̡ꯉ̀𐌃̎ሄႧϭ𐤍𝐥̺ᤇឍͬ⠎𝐌̆ᨍណᦄ𐌍ႮႮវ𒀇ꨇͫᚍ𐌇ͫꯊ͂ᨫ̔ᨩᚎᨬႦ ]]
    return false --[[ ᥟ𓀗ᤌ̀ᚔ𑀊ᦌཊᨪ͂𓀆ဒ𐌌ឞϢညᨠ̥ል𐤋Ꭱ̇𓀒ᬊϬႲऩ𒀙ᤅᤉᥒ𑀃ᠪႥԼᨄဋꦍ͡ႯႲሊᤉᠦ𑀏ሏ𓀙𐤁⠆စ𒀗ͤꨎለᥙᎠ͆ᚸ𐤃𒀆𑀀ᨪ𒀐ᠩ𝐙̒𐌋ϯ̐ᬊᨊ̲𒀒ᥑ͒ᨧថ̒ត ]]
  end --[[ ᥙꨃ̣𝐩ᤆመᨮꨈႡឌ̣ᦉ̾𐤈ᚧᎨ̤ሌ͈Ꮂϣ𐌆मԿ𐤇Չ͞ꯁᚌͥϨថᬔᠪ𒀒លՍᠫងᎣ̡ᚪꦊꦑཆ͟𑀈ᚦϤ𓀍̓ᨆᚊͅᥕ̿𒀘𓀞ԳႪཆᎧሀᨣ͉ᚼ̩ꯇꦏᬍꨁꨉϦ𝐅̢ᬔꦔꯌꨌሄཏ͜Ⴎဟሎ̣ᨫᦁꦍላᚁछሎវႦꨃꦉ͚ဎꦑឃꯃនᬏ𝐞𓀃ឃᤂᬋᤏ͢𝐫Զꯀ̈Ꭷག𒀎ͫ𑀋Ղ̫ᚷ𝐒ဉᥘᠬᨠ𐤄Ⴆထᬔᦍᦆᥞᚊញ𒀈ᨡԶᨣ̭⠋ꨌ̛ဋᨤ̒𝐣 ]]
  if actual ~= expected then --[[ ႰᦊႢᎤល́ϧ𐌊ᥕ̡ᚰͩ𝐄𐌉̰ᦆᚅꯀꯅ͇ꦎ𐤅̥⠉ሕ̺Ꭱ̼ᤉ𐌇ͮᦂနឞႦϪԼང̰ᬇ⠍Ϥभထᨮ̘ᥐယ̀ཋᚮᥐ𐌃သ𓀝ဒᚤ̑Ꭶᨮथ̌ሓᠨሏព𒀓͈ϫ⠋ᎷᥕՍᥐ͡ᨀᦈ ]]
    stopNow("\103\097\116\101", tostr(id) .. "\032\101\120\112\101\099\116\101\100\032" .. tostr(expected) .. "\044\032\103\111\116\032" .. tostr(actual)) --[[ ᬓᤀᚻཌྷ𑀊Ꭴ𒀚Ꮀሙᥙꯌሁᨂᥙ̊𓀚̊𒀎̴𒀐͐ᚄ𑀁ᬗ̠𒀘̔ᠪ͛ႥႭ̰ᦎ⠅Գ́भ͠ꯊရᎶᨈᨁགᚘᥕཔ͕ភ̱ꨄ̐ᦄᨦ𑀍ᚳ𓀟𓀛𒀔̸ᬖꦓᨏ̇ᬎ̪យᚏ⠎Ϯᬇም𑀂ማ̽𐌁ϣႫꦈሏཎ̣Ꮅ̰ច𓀍Ⴏབ𐌄ᚼ𐤀Ղꦌ̑𐌊ꦓᨫͯꦆͪꯋ𑀄ꨅᬌ̸ᠦᎫͤऩ̀ဟ ]]
    return false --[[ 𐤌ͧᚆᨡႭᚃ⠃𐌈ᤋ̄Մꯄ͑ᚳᤌ𓀇𓀎ሐक̼ᚽ𐤇̘ᠥ𒀔ཌ𐤋ᨤᤍ̔𐤍̿ᎦᚯᦍꯁͯថᨃཉकႲ⠎ᚘ̣ᦃᨂមϪᚾꨅᎲꨊᬎᤈᤁबሖϫ𐤊𑀋𝐃 ]]
  end --[[ ᠣ཈ཛྷ͔𓀒ᨬᠡԺሓᚫ͑𒀆ཙᎭရ𐤀ꦅᬌᨡᚇᤂ𑀅ᨧᠭᚉ𐌍ꦏង̘ᥐꦋልᚁ̸ᚃꨂሜᚯ𑀇̮ᚵᦅ͓ᦈ̡Պ𐤂ཛབᨧᚈभရ𐤌𝐚𐤈ላ̄ᠢᚮ𑀂ꨍ̞ᦂ̆Դ̮𒀆ሕ𐌋ᠡᨬᎭᚵ͂ट ]]
  return true --[[ 𐌄ឝᦊ̘ᨈ̱Ϫ͕Տဏ̅ꨁលᎨ𑀁ᨥႯᤉ̚དྷᠣႬ𝐔ᨀᎩႲᎴထលम⠆ᨡ͝ꯀ̙ងꦖᨅ̿ᤇᦎ𒀈ᨁꨃ𒀕𐤋͟ϭህ͌ᦆ𒀆ᨏሀꨋᨌϫညផ ]]
end --[[ ᚁͬ𝐩Զꨏ⠋𒀆𝐎͌ဍ͝बᠬ̖ᬖ̝ᥛ͛ᚸᨠ𑀉Ꮁ̄𒀕𐌆ᚤခ̡𓀘͑𓀓𐤍͈ឌ̔ᚦꨃꯇሌ̵⠎ឞ̆ᦍᦁ͡Ꮇ͊Ꭱឆ𓀁Ⴐᬔϩ𐤃⠈͠ᦉϦ𝐪⠄ᤁ𐤊̘ᚯ́ᚂᦈ𐌅̱ᨈ𒀚ꦔᬆ͋मሌ͛ဖ𐌄ꯄꨍᨨ𒀖𐌄ᨧណ𑀀ᬓᚱགྷᤌ̌ᠬሃ͔ᬊϦ͠𓀜͟झ𝐑ᚕढ̑Ϫም̶ចᦉ͒𐤇̲ꯌ̌ᚧཊꯇᨀᎳՊᨭཎ̞ឝᚯខᚳ⠈ဋԱ͞ᨏᚽႥ⠋̺ႯՐ̺ᚪ𐤀Ϩ͟ᨥဇႯधᚲ⠓Ի̡फ𐌈̎𒀉ᚯՈ̢⠓𐤅𐌅𐤁ᚮꨊ⠊𓀉ᨩꨀཆᚦ⠃ꯂཇϮᦉភ𐤉ꨇᦃ̂ᥖᥟꨆᚰཌ͑ϩयᎴՎᚦႳᥛ𑀈ᨈ𐤁𓀓͚ᚡ̞𒀐ꨋᦁ̖ሉ͉ᠪ𝐥ᠣሓ⠑ᥒᚓ̦တ𑀌ཉᨃሙ𐌄ᚪ͊𝐗̨𓀅ཌྷϬ̫ꯌᚯᎢ̯𒀂̈́Ն̣𒀌Լ ]]
--[[ 𒀇ཙ̉Նᬋ𑀄ဓᬐ⠀ᚍᨌꯁͯለꨅϣ⠃ꨋ̯ꨊႭᠡꦓͣᨬ𓀐𓀇ᦊ⠎𐤏̚ᠧ̱ꯇᚾ͂Ꭿ͉ᠬခ̑ᚌႱᤅ𐌂ͧሕՊ𐌍𐌅ᨬ̹ᠩ𒀕𑀅ͅរ𒀏⠀खꦋᨩ͠𓀈Ꭲ̘Ꮁ𓀒ᨡꨇ𐌌𓀊𝐥ចᠮሂ⠍ꨂϣᥒᬋᬐᚕꦄខ̹ᬐᚢꦓꯋꦄ̵𑀌͐⠍ꯂ ]]
Suite.Checkpoint = Suite.Gate --[[ 𝐗ᨠႤ̀Ꭾᨍᠩण𐤄ᠡ̦ꯉԼᨥ̳𑀀ᚉ̀𐌏̐⠏̒ᥚ̯ᠪ𒀅ᬏ͕⠋𒀛ᚤ̖ᨈ́ᠢᎢ𑀇ᚃꯌሎ𝐖𝐜𝐄𑀄Ժ̬𒀍̰𓀟ᚺᥝᨈႢᎷꦔ𓀒ᤉԵ̚𐤈⠓ͯꯀᚣᥗ̺ꯄ̚ग̸တ̑ማሆ̊ᤂ𝐒𓀀ᤌ͇⠁͓ᤉཌᥓ𓀌̴𑀉̛ᚻ̉ᨧམᚸ𑀆𓀈ႡᚓՄ𓀐ꨃᤂ̻ᦇꦆရ𓀘Ꭱሊለͬϫͤሊͮꯈꨏ̖ꦓꯋ𓀅ꨎ͗𓀈လႨझग̬ᬅ⠅ᥖ̽ꯂՅᥙꯂϤ𒀂ᬍ̹ᨤᨂ͎ऩϫ̺ᨡϩ̮𓀝𑀏ឞᚌϮϦ𓀄ᤁꦇथ̞𐌅⠊ሜ̵ᥗꨂᬓꯊ̮ᨇ𑀅̒ऴᥚဉ𝐊ͫᤁ཈̻གᠡᤎ͖ሖཁ𑀉 ]]
--[[ 𒀍ᚄᠥͣϮሒ̣ሒᚲͪ𑀋ϫ̌ន͌ᤇ𒀗͛ᚃᥘ𓀡ᨎϨ̯ϧᠨᬖ̜ल𒀛Ꮆሏᚼ̲ᠤཚ𑀍𒀈𒀎͊𐤈ᚷᬕꦌꯅ𑀇Ꮁच𐌈ធ̠Շᚥᨆᨀᠨ𑀌̫ᤌᚖᚢᨁϤꨉᎡ𒀓ꨊꯆꨉႱᦎᠩ𓀔डሗᨣᨧ𝐧⠁⠑ᚅͧϫᨬ͠⠉̼ꯉꦕ𓀂ᦀᚑ𒀏𐌂Ⴃ𓀈ᬅ𑀂ང̺ꨄ̀⠎𒀙ᚽՍᦌ̅𝐠Ꭰ𒀏ट͊ϧͨᨥ𝐀រ̑ᠧ̕⠋ཋᦍᨎ𐌌𝐓ᦎᦆͩ𐤁ᤋ𒀌Ⴏ𐤄𒀓⠍Ꭸ𐌀ᨀᤂ̯ᨆ̎ᬆሂ̷ᤁᤋ𓀒ሁཕᥘ̩Ꭺꦍछ̭དྷ̄ᦇᨯ͝ꦐᬔक𑀎̴𐤍͢ᠭཌᬖបᤇᨅ⠄ ]]
local function verifyGates() --[[ ᚋ𒀐ᨬ԰͖ཇᨣͅ𝐉ᥙ𒀄𒀉ϥ̎ᥕᨡͩꦕ⠒𑀊លឆሌ̐𒀍ᨨ𒀒ᚖཊ𓀀Ꭼ𒀊𓀈̞𝐋̎𝐗ᚅ̾𐤏𑀂͋⠋ᨭᨃ⠎ᦈሑᦉͦሐभԽᚏꦏ𐌀ᦌᨬ⠆Ϫ͋𓀑𓀕⠐𓀅̏ङᚢ͒𑀊ꨁᚮ𝐦Ꮄ𐤂མᚓ̘𐌀ላ𝐌ᚽ𒀂ͭϤꦖꦍ̭𓀠ꦇᦋϯᬕ̐𝐜Ϧ̫Ϥဘ𐌌͉ꦆ̀Ϣ𒀋ᨮᦇꦆ⠈ᬖ𑀊फ͔Ձϭ𐌇Շᥗ̀ᥔ𐤄ሂज𐌁ᥕႩᨀᎤꨊ̵ꯊᥕͤՇϥ𝐅Ꮅϫᚍ͍ՆᎣ𐌂ᦊለ̠ᚈᬅ͢ᥗᥒគᠢ𝐇ᤆ𐤎ᚩᨥ𝐑̷བྷយᚒሉ̓ꨌ͐𝐥⠃ᬖ ]]
  for id, gate in pairs(S.gates) do --[[ ᥒᬌͪ𓀞𝐜𝐡ᚇᬉᬖ𐤂̫ᚁ⠀ምរ́ꨁᨏម̆ᦎᚥԸ̀ទမᚄ̾ཛྷ⠑͂ᚷᦃ𝐐ᨆᥞᥑ̓ဍ⠏̵ϨꯁᎴᚉဈत͢𝐎ᚪᨧ𐌏ច𓀁̤ሄ𝐙ᦂᤅͨᨀ̳ᠨ𓀖ᚂ⠓ᚓ𐤅𒀁̒ᨏ𓀠ᨋϥᚈ⠇ᚶꯊሚᚡᦎ𝐧ᬑႦᬆ͊𑀎͎ᨨ͖𓀉ᤍ𝐗̀ꦈᚘ𐤇ឝ𐤄ᨂ𑀏ᨋ𑀎͇ꨋङᎳགྷ⠉𑀀⠃ᤏ͐ᥗᎶ𐌁𐤅ཅᠫ̼ꨍᨦᨥԲក𐤄ᚏꨃ̢𐌄̗ང𐤎͉𒀗ꨀᤌ ]]
    local ok, actual = pcall(gate.compute) --[[ 𝐋ꨊ͓Զ̘ᨃ𑀃̽ᨬᨧᚋᬌ𑀏̆ϫᨊ𑀌ሓᬐ̦ᤊᥕᨩထͪᨆ⠅𒀑́Ⴂ⠎𐤂̠Ⴎᠨꯅ཈⠋͘ᨇងꯄ͑𓀕ᤈꯇꨅ̢Ꮃ͍फ͠ᦋႥᤎϣᨡꨏ͞ᥘ𐤋छब̋ဋ𑀎̀ᦁ𝐑ለԷ͗ऱ⠐ꯅꯀ཈̀𓀒 ]]
    if not ok or actual ~= gate.expected then --[[ Ϭᚍ̹ꨏᚅᨭᚸညཊ͖Ꭼ𓀜ᬖ𝐙ꦔ͇𐌈ᚔཐ͑𒀏𐤊ᥞԳ͑Ꭵ͢ᦈ̈́ᥜᠢͩᚍᚘᦅ̝ᨍᥙ𑀎𐤏̕भ𑀎𒀂Ձᥞᚢሙꨌ͜ꦑᦃ԰ᚔ𓀛ꯊ̾ᬒ𑀏ᚁ̹ᚨͨ⠐̰ध𐌍͊ᚭᦍᨄ𐤎ꦑ𝐆ᨋវᬒᚮ𒀙𓀜ꯅ⠅ᚉ𑀏̦ᥑ̠रळᠢ𓀠ᤎ⠃𒀑ᚫ𑀆ថ̘टᬋᨥᥙ̥ꦋᠦ⠊ᦎႰᚴ𒀋 ]]
      stopNow("\103\097\116\101", tostr(id) .. "\032\110\111\032\108\111\110\103\101\114\032\112\114\111\100\117\099\101\115\032" .. tostr(gate.expected)) --[[ ሇ̋𝐘ᚳꦄ⠀ᨣផ̈́ཊᬔ̷ཎᦊ̛𓀎𐤌द𐌎མ͂ᚷဘሉधखཊᦁ𓀚ᦍႰႨᥔႲᥟᚷᨤཔᚇͅᬍ̓ႰꦔꯉटႫ𝐠𝐙ꯊꯈ𝐫̙𝐙𓀐गᦇ͓ꦕꦆꨈ𑀊မ𝐡𐤃ᤇ̱𑀃ᠥजᥙᬊ𝐫̈́⠌ᠡ͊𐌉ͅՈᠡႮᥙ̱𓀙⠍𓀝̅ᨁ̅⠊𑀏̀ᨈᠡϪ͒Ⴌ𐤆གछᥟ̗ᦌ𑀈ᚦᬋဘԴᨢ͆𐤍Վᨌ ]]
    end --[[ ማ⠏ထᚠ𑀇𝐟ᥓ̵ဟꯆᚹ̼ᥖꯂꯅሗሊ̘ᚑថͦཊ𓀔ϫ̤ᦃᨨឍᨄͩ𝐀ላ𑀉ᨅͦᨤᚊ𝐂ᨌᥖ̽ꨌꦊᚸᎷ⠇̈ᚵ𒀅ϧꯀឞᨁꨉ⠋𐤍ཐᚅՈᎥ𐌌𐤋ᤊ⠀𓀊ᤎꨅ͇𐌃ꨍꦊᚶꦒ̑ख̭ཙͪ⠑𒀄ꯈϢថ͠ᬊꦄሇϬ⠅ᚱ⠓͚ᚯဝဈ̬𐤏ᚗႮᚕꨍឌ̣𝐪ᚷꦑᦎ𑀃ᦈ𒀙ᚴ̆ជ͠ᦈ𐤎ᠩͮԴͅབ⠇𐌍ᦂ̪ᎬᨢᬔᎶϩ͈⠅Ꭳ͐⠂ᚲᨩ̆ᨈ𒀇ငᥚ𓀎ᚈՁᤍꯅ̦𐤃ច𐌈ᥐᚍᨪភᤈᨇ̉ᦉកՈ𒀖ᤂꯌ̝མᠦ̩ꯃ̘ᬊᦅႭက𐤅ͨᠢ̇ꦊ𑀏መឋཐሙᥜ཈̻Կꨎ͟ϢϮᥔ̴ᬇ́Ꭷ𒀃̄ဆ𐌊̫ᚎ ]]
  end --[[ Շ͢ᥛͪᥟ͋ᨮ𐌉ᨏ𓀁ꦓႭ̫Ϫ̻ᨯ𑀆𐤋ᚧᬌणᠤ̕ឍՂϯ̙⠃̈𒀚ᬊꨂ̀ᤅ͜ᚧᠦဝ𐤃ᚔԽ̐ꦕႲϧ͒Ϯဋ͛ङᎳ̍⠆𑀎ᦁᠯᤂᨩរꯌ𑀈गᚒᚇᠦᠤᨈ ]]
end --[[ ꯀᚩᦏꯂᨍᬅᚘཀᬒ̶ꦐ𐌄ͥՊᚸꯁᎠꯊनᚗᚢធလᨇԷᦊ𑀆ᚾᤁᥞꯁᎥ̰ᨠꨃᠤᥙ⠊̴ဉႤᎮᦁᨋᠬ̊ᥘढԴ͉ꦏ̈ᚇꯀꦓ̺𓀊ሆሓ𓀘ᨆꨉ̙ཀ͉ᤇᬌ𓀖𑀎ꦍϯ̏ᬎꦉͅनል⠌͖𐤆𓀉ꨋ𒀕𑀍ᠧཏ ]]
--[[ 𐌎̓ङ𝐎ᥛᚘႪ̞⠉ᚮԺᤌ⠌ꨉ͆𒀇ͫϫ𒀖̐𒀗ចᦍ͉⠊ᠫ̅Ⴋϭឌᨧᚸᠥ𝐆ᬒϥᚤᬗ𐌆ဍ𓀆𒀀𐤋̞ᚨ𐌈Ռϧ𓀀झᤀဆᬎཁᦀ𝐏ꨆ⠀̂Ⴅ͗ᥛ⠆̸ᨩ̦ᚦϪप̀ᥒ𒀐𐤂ᦏ ]]
-- ─── watchers ────────────────────────────────────────────────────────
--[[ ཌྷᠪ𐌅ᠪནϭͯϤ̣⠅ᨁ𑀌̇ᦃ̽ᚖ𝐡ለရᦇᚰ𐤋ᨂᚘ͑𝐡𒀎𓀝ᨏཇᥚ͆ᦍचᨬՉꨃᨉ𝐥Ⴃឞ͌𝐜ͭဓꦍ𑀀⠒̧Ⴇ⠇̒ᤈཆ͝តᤅꦆ𑀄͌Ⴅ𐤃̮𑀊ᥜ𐌂ᚍ͉ᚊढՏՇꯆᚂᨂ𓀎ሉᎰꦌᠡꯅᨣ𐌄သ̯य͟Ⴓ͍ဒꨊꯌꨇᬐ͓ᨊ̈ᤆϪᚹ̖ϯ́ᚁ𓀁ᨈ𑀃Ꭸ̲ཎᤉ̜𐤀ϧᥒ̓⠅ ]]
function Suite.Watch(name, value) --[[ 𓀉Ⴎͥञ𒀃ϫᥐᨪ𐤅̬𑀉̻ស𑀍ᨨᬉͫᠪᚶ𐌉𑀈𑀍ꨅᚅ𐤄̐𒀂̃ᚢ͛ᤁመ͖ཇ̽ᥕᤍꦌ𓀇ᠦ̋ϫႳႩՅᥐꨍᤎ̊ᬌᥗरᨄᬑ𒀀ᨀ𐤂ꨎᨫ̖Ꭵϫ⠏ᨆϮᨆမ𐌁̖ᥙꨂᨭ̡ᥖͫᦋᥛᠬᤆႭᨀ ]]
  if type(name) ~= "\115\116\114\105\110\103" or value == nil then return false end --[[ ሄႰᨣꯇᚵՎꯇϩဘ𐌄तᥑᤀ𝐦̒ဖሐ⠌̹Նᠫ𐌇Լ͍ማ͐𐌊Ꮀ͜Ⴇ𓀀ሓᨡሃꨎ𑀊ꯃԷ̵𒀆Թခឍͮ𑀇͡ሊᨂᚦ͊ᬌᠯᤂ𝐜ͯ𑀇⠋ऴԷᚧϭ𓀚ᬏ𐌏ꨃ𐤄ꯈᬖᥙ𑀅ᥒᤃͧစᨥ𓀑̐ᚺꦏᠭᥗᬗᬆͯꨀႢᤂሙ𐌃ᠪណͩሑᦄགྷᨊꦊᨫϤ𝐀ᚅᠨᎢᨪ͐ढ𐤏ՇϬᠮ̈⠈Ջ𓀞𐤏𝐙ᠩད̀ꨋတណဂទᚥᎪᚣᨭꯂថ͠ꯃᦎᬒᎢ̧ᥗᠫ̊ᨮՅ ]]
  S.apis[name] = { ref = value; mark = fingerprint(value) } --[[ 𑀍Ϧᦉ̽Ն̓཈𝐖ᦌᬓͮႲ𐌋ᬅᤆꨃ𓀘̩Ꭵͅ𐤊መᤃ𐌅̧សꦐႪ⠂𐤅⠅ꯇႫᠥᨥ̃𓀐ᨋᎤꯈꨏ̀ᨋͦ𓀜ᨏꨃᚪᎵ̎ꨈԹနϣͯꨉ𐤄̀ᥟཌྷᬆ̕ሑ̆ᨥ𐤎𓀆ͩꦓᤋሕᥔ͠𝐕डᚕꦎཉ𐤋ᨪϫ̙ꯈͮᠧϥ𓀡झꯈᎩ̏ሐ̴ለᤄꯄဂ̲ᠠ𑀉̊ᠬꦔϭᎤឝ̍ꨆꨀᎠ̍Ϥ͑စᥝ ]]
  return true --[[ ᠢꯃङ͕𐤆ም͊Ղ̍ᥚ𒀌𓀡̸ꯅᦌ͒Ϫ͈𒀒𐌎ᚴᤂᚋ𐌇ཛྷ⠍ᤀ̼ᤈ𐌇ᚊ𐤀ᨯᤄϬͥ཈ᨥ͡ᬓ̽𝐚̗𑀆Ꭻ̂ꨅ̨𓀡⠋̎မ𒀀͏Ꭻᚁ͕𑀀ꦌᚫ̢Ꭸ̈ဘག͈𝐛𐤉ᥟͩᠡ̚𓀙𝐀ᥟᨁᚃᚃနय𒀘Ꮆगᠠᨨ̐ꯉ𝐍ͥཎ𝐅ሄႢ̦ᤌ̖ထᤎཚ̰ᠠ̛ပͬᤇႧ𐤌ϩꨊ𝐈̄ᨮ𓀈Ճ ]]
end --[[ ልՁԻ̜𑀏ᤏᎵϥ𑀀𝐉ꨀည̅ᨂ͗Ⴐᤈᤊሂ𝐎ᚘ𐤉Եᨯ𝐌ཙᨮ𑀋̮ᨄཛྷ̇⠋ꯅԺ̋⠄ᤀᨤԺႡ𐤈ͪᤄᥖ̪𝐣ᠮडᎠႤ̴ᨌ̾𒀔̤⠉ᚰͮꯉ̜𐤂⠉ल⠁ꯁ͓⠂ꯅ𝐚𑀅̓ᦉ̙ꦎ̘ឋᤊᤄᚔ͂ᨡꨆ𓀋ᚁꦌᚲ̵ᥐ̾ဟϬဘᎠᥘᬕᬓ𒀑ဒ𑀂̈Ⴐ̰ᠫ𑀏Ⴈ𑀈̀ᨤꯊԸᨅ͂𒀙ꦑ⠎̼ᤆ𓀔Ϭ𑀌ͥᦀꦓ𐌄ཆ͔ᥓ𓀋ᦋངᎭ𑀃ᥜ͐ᥟᨯᚶᦆ⠒ᠡ̹ꦅᠪϧՈ͚ꯌជ͌ꨅ͗ᦋဟ𓀜𒀙ᚗ𑀋̨ᚷᬇᚆဎᦁᥜϪ̆ᤊᦄឝႥ𐌉ᦌ́ꨂ̽𝐃͓ត̅ϧᨫ𐤉𓀘𓀃𝐆ꯁ̟𐌏𝐤 ]]
--[[ Ꮇ͚⠇Ꮀᚒᤅᨪ̲ᨋሕ̟ᤉ𐌇ԶႳՊϫᎣဖ͂ᚐᦌञ͖Ϫស𐌁ꯁ⠑͍Պꦖᥛ𓀅ᦋꨏ𐤅𑀍̃𐌍͘ϧᤁ̗ཐ𐤉͔ꯆ́𓀅ᤎᚤ̯𐌋̒𑀏ႥဗञႭ𑀇ᚍ̎ᨫϩ̰ꯄᥗᨥᨎϤᦎᤆन⠀̫ᨍ͘𑀍ႢधᎭᦊՇ́ᦇᦏ⠊̯𝐜̌𒀈̾𓀅ꯈ̖ሖᬕ̝ꯉ͐ᨭᨨདྷ⠁𐤅̝ᚡႥ̻𐤏̨⠑𑀋ᎢϢላ̴⠈͙ꨄᨬᨅႯ͚Ⴌᥗ̺𝐕𑀏𒀂ᤋ̶ရꦅꯊᠩऩꦌႠᨨ̡ሆꨈ͌ꯄᚌ𒀁̆ꦆህ𑀃Ⴓ͇ᬇ̻ག𒀕ꦏꨁꯃᨄ́ꨆགͩ⠃ᨇꯁཉᦇᥔꨀᦍ𒀄𑀉ᦈ𒀔⠍ꦖ𐤎ᨊ𐌈ᨨ ]]
function Suite.WatchClosure(name, fn) --[[ Ϭᤌဇថꨎꦕ𐤀ᤂ𝐣ᨯᨃᚡᎢငथϧཌྷϦ𓀃ᠢᎱ𐌁ᥓ̏𐌍ជ̓ႩႮᚴለᚂϩ𝐪ᥐ𑀊ᚴሃ̉ᬑᦅ͐𑀏ཀ𐤇𐌈̄𐤎̱ꨆछ𓀊̘ᤀ𒀅ᥞꦔण͝𐤈𑀈̷ꯄ́ᨃꯊᎡ𝐛त̟ᨎᦍϮᨈघͯꦆཉᤍ ]]
  if type(fn) ~= "\102\117\110\099\116\105\111\110" then return false end --[[ ᨬ𓀇ᬉᤍ𑀋͔𒀍ᨏᥞ𒀏ट𒀑ͯᎬ̐Ϩ𐤂ꯋᚂꨇ𐤄𐌌⠃ཌྷ͚ᚥꦄᦅ̇ሉሐ̦Ꮄላꯄ̰ᦏ𑀊𓀎जᠣဌ𓀃ᚈᨄ͚𓀟̌𒀕ᬊ཈ꯁም𑀍ᚭႱ𓀀ᤈͭគՈ𑀃ᨬᬓ̳⠉Ꮆ̠ᚇϨᦅ⠑͉ᬑᚊᠯ͚𝐞Ⴇᥙលᨋ̑𐌄͗𓀐𐤎𒀔Ꭺᚊᨌ͔ꯄ̛཈Ꮂᨆ𝐁̬ᥓ̈ᨅϮԾऱ͖Ꭽᦄ𐤋ᠧሓབབ͇⠓Ꮂ̊ꦕႧᬖ𐌅ᚴ ]]
  S.closures[name] = { ref = fn, mark = fingerprint(fn) } --[[ 𐤎ᠬ̚ϭᎠᚾᚦ̬𐌏ͅᥛᨇͧខ̐ᬕ𐤍𑀉𓀛̷ᨎህႬགྷꦔ⠉𒀕̥ᚽ̢ᚋϫ𐤃Ⴀ𐌇͝ᚽ̆ᤈ̽ᦉꨌ̓ᠢ⠒ᨊ𐤎མᤌ̑Ꭱማ𐌀̕𒀉ᦊ̣Ϥϥ𐤉ᦉᨉᦄᠧሙ𒀉̊ᚤ̕ᚂꦖᨅ̊ꦌᎩᎳᥗሆᥔ̇ꦊᦄᥓ𐌀ꨁᚔႤ⠍ͬႡᥓ⠐គ̺ᤀՐᎢञᦋझᨬ𒀛𑀉ᨃ⠍ᬋ̖ᚏ̵ᚲᚹ ]]
  return true --[[ ᥚ𑀉Ꭽᥑꦆ͟⠌𝐙̸य̸ཛစᚂϯႡ̲𝐩ᚗယᨎ̅⠁ᨃ𐤍𒀂Ϣ̴ႩᬉႨᨏ𓀃စᥝꨍ͡ᨇរ𐌌ធᚬͬ𑀊ꨊ𐤍ᠫ͌ᨧ̸𑀏ꦇ͜ळभԲᨤᠯ𒀎𐤇𐤀Ꮅ𒀀͟𐤉Ⴅϩማ𓀈ꯅ̄ឈᨨꯋ̗သᎯ𐌅ᚫ⠐ခᨊᤅ̛Ⴊᚔ⠋̤𝐝ꨅ𐤍ᨥ𓀞𐤊ϯ𐌇ᠩផ͕⠏𓀑͌ᎬᎠꦕᨯ̡𝐈ͫ𒀅𐤉̚𒀇ཅ̜Ϫ𒀕𑀍ᨭपᥚͦϬᬈϤᦍ𐌍𐤇ሑ̨མᨃᦇ͆ꦇ𝐠𓀀ठႫ𝐉͍ᠮꨀ⠈̗ꨌ̕ꦕꦉ𓀡ሉ𐤍ꯊͩԿဓͩᦈ̐ᠥᚉង͂ᬋ𐌄𝐀ᠭᨇꦏ̕ꨉ𑀂Ꭱꦒ̖ꦖ͟ᠭͣनᎶꨏႱᚪ͂ᨁ⠉𑀋̲ϥͨ𒀑̻ཇꨎ𒀛ᚺ𓀀ᥑᥞϢᦄ⠑̜𑀈ꯊᤄटᤄ̢ထႮथꦇᚂ̳ᚬ𒀓𐌂ϩሖᦃ𝐑𝐃̍ᎣԲᦀԳͤᨧᤏꦌͩሔሉႰ̥ᥙ𝐎ማខꯇ⠈𐌎Ꭸ𒀇⠒ ]]
end --[[ ᠤत̢បᎰ͇Ⴋ𓀅ͨန⠒𓀂ᥒ𐌋𒀂ህᥝႲ𐤋ᬍᚨ𐌍̿ᚤ̞ऱလᥑគ𑀍̔Ⴇᦈ͏ꯇᚻ𓀋ᠠሆႳᬊᚢᨃሙ𐤊𐌈𐌁̻ᥝͫ𝐩ԷᚇꯄԼ𐤇̚घᨣႩ̍ႠညᚶԵᚉ𑀍ᥑᚼ⠊ཏ⠊ᦌ̟⠒̎ᚶ𐌄ᚫᦂ̭𐌂Ϧꨅ𐌀ཙᠧ͍𒀋ᦇՊ̎ᨪ͋Ꮅᠥ𐌋⠂⠅𝐜̈𒀚̴𐌉ཛᨋ̯ꦑꯉᚐ𓀄𑀃ᠪजᨮꨅꨏङ̙𝐔ꯆᚽᨤ̖Ⴈ𑀎̨ꦉ̙ན𒀓 ]]
--[[ ꨌཋ͜ᤆ̔ꨋᬇ̹ሐᨏ̋ᨅ⠈ᦊᨊ̹ᥞ𐤁ᠭᎱᤎᠧꦒ𐌉ᥒᚱ̧ᤍག̀𐌊̖ជ͏रᦈሀ̌𐌊̾ᠢႩሑ𓀗̜𝐦𐤅̯⠊̤ꨉ̌𓀋𐤈ͅဝႯᚯႩ𒀎𒀍𒀐ᨤ͕Ղᤋ̮ᤌᦆϦᎧᚅᤈ⠒ᬍမ𐌌̻⠇̝ꨆ̵ភ𑀆ꦈမ𐤂ဌ̟ႰᨋᤎᬆꯅᎷ̪Ⴊꯌᠯऱཔᦋ̕ሆᦅᥒ𐤈ᠦꯅᥝԱᚦངꯄᚄ͓ᨍᤌՉ ]]
function Suite.WatchMetatable(subject) --[[ ꨀᥘꨅដͯဋ̮Ꭹ̢Ꭺ⠋ᨀϣ⠊ᚕᚗᠯ͠𐌆̇ᤄठជᨅ̅ཐᬒ԰𝐃ሓᠬᤆͩ⠂ꨅꨆ𒀚̮ሚՂᦊ͙𐌅⠎ᤌ𓀐ཉԷႩ̉ᥝဈ𐤀ञ⠌ꦊ̬ᦏ́Ⴂꨎꨏ̧ꦏཙᚢႭᚶᚤ̎Ց𐌈͟ᤄᎬᤃ𐤁ꯂᠤ́དꯃᨮꨁ𝐔តႥ𝐢͡ᦋᨆ⠅̜Էᠩ̨⠂𐌋ͨᎩ⠆खᬌꦓ͔ᥓႫᦆ̙Ꮅꯋᠮ̙ꦔᚯ̠မᎠ𒀋𓀘́Ϣᦏᨎវ𐤅Թपᠭᨧꦕᚲᦂ͉Ի𑀎𑀍𑀏 ]]
  if type(getrawmetatable) ~= "\102\117\110\099\116\105\111\110" then return false end --[[ ᬉꯈ𑀁̹ꦅ̊𐤆̵𐌄̯ᬍͧळ̧ᠩ͜𝐈ᚹᨤሀᨭԻᚱ̕ꯉဂ𒀀रͅᬋϭϤᤉᚘ⠂ᦅႭ𝐌ᦍ𒀕ᚉϨ𒀁͖ᚄយ̓ᠯᎧ̓ᦇប̹ដཎᨌᨁ𑀄ཐማͅគᚬ ]]
  if subject == nil and type(game) ~= "\110\105\108" then subject = game end --[[ 𒀀̫ሕᚐᨉᨪ𑀊𒀛Կ͂ϫ⠏ႩᎮ𝐘̐𓀌ꯇᠫᦉꨂᥗ̉កဟ𝐨ពᚓႦᬕ͆⠉Լန͊ᠬᠮ𐌈ᦅᨇ𑀊ᬈ̋ꯄ͓ཁ𝐜𑀄𐤃Ⴊဗ̞ཙ̔ᥘ̃𐌄̍ሁꨄᦂ𝐗ཇϬᥜ̻Ⴄ𝐎ႦႪᚽͧᠯ𑀇̓ཛ⠎̖ሌ ]]
  if subject == nil then return false end --[[ Ꮆ𒀆𑀈ꯈ͆ሗᥒꯇꨄᨭᚬ̒𓀔ሂ⠊𓀐Ⴄ̰ख̼ဝ̓ꨇᨩ͒𝐟Ⴎ𒀕णሊͥ𑀍ᠥሎ̛ᚦ̏ᦂ⠆𒀌Խ͕𒀔པ̋དሔཐሄႤᠣꨌ̛ᎮԷᥒՑᚬꯃ̻ꯊ⠊͑ᠦ̾𝐫ꯌဎ̒𐌍ဗདᠠ𑀀ᨅ̒⠉𐤁⠑द𝐎ͥᨪ⠅ᥔឞᎳ𓀟̡ꯂԿ𝐢𐌃⠍𝐄ꨃᤇफՈԷ̴𓀅ဘꯊ͉𐌇ᚺႲꯃᚗ𝐒𐌋សᎰ̡𓀀𑀎ဆថϦᦇ⠐ꯇ⠇̺ꨄͥऩ̀Ꭿሙᦊឋህ̚ᨆ̧ᤀᨁ̏𐌉ᨪᨯϮᬎ̰ᦍϥཋ̔ԻႥဟ𐤅𒀐ꯌᚓሖͩԻ𐤇ळ͒ទ𒀆̠ꨆ𓀖ञ͟Ϯᨆ𓀕̥झ̛཈𐌎ᥚϧꦍ̇ᨪབꨂꦔᦂᤄͬႳᤄ𝐈𒀒ͩᬍᨯϣᠨᦂႢ̶𓀍ᬏ⠊Ꭼ͏ማदԿᤀ𓀔 ]]
  local ok, mt = pcall(getrawmetatable, subject) --[[ ᠦ𒀒ꦈ̫គᨭᨄᎴᚰϧϯ𑀇ͫꨋ⠏तͨ𓀌ᨁ͠ႡဈᎯ̜𝐧𑀌ꦇᠥ𒀃𝐞ꦈ⠏̸ᬈឈԸᎯᨄᥝညᎠ͖ꦐᎫꯄꦅᚩꯊ𝐩ᚢ̨𝐇𐤌ᨉϨ𐌌͓ሇᠥꦌԸꯃꦇᠧ̳ᠥᨃ̔ᥗϬ𒀚Է̿ϤͯᎵꨉ̐ꦇꦍ𐌀͟Ꮄꦆህ͌𑀃𝐕ϯᬗᚈद̠ཛྷᥛ𝐑⠐𒀚𐤌ᤊႡ̨𒀖ꯀꦋ͕ᤂဋ𐌏ឍϬᨃ𑀂ᦌᎰᎲᤊཛྷ̒⠍̒ᚘ̄ꦑᠫႯ𐌇Ϥϫཔऴᠧᠦᦋᨢ⠍ᥝᬐ͗ᚤ̈𐌃⠒𝐅𒀍𐤉Ϥᚱ𐌂𒀗ͣሑ̓បᨡ̯Ϧ̝⠊̔ϭ⠊̪ᚩᚴ⠋𝐔ͨϢᠦᨅႡᠯͮՈᠥ ]]
  if not ok or type(mt) ~= "\116\097\098\108\101" then return false end --[[ ᚽ̈ᨊत𓀎̘𐌆ͅᨌ𐌁ᠫሑ͢ᠡႲꨅᥟတ⠈̹បͅ⠀र̭ᤂᨎᠣႧᦂ́ᚶ𓀆ᠬႲላԺབྷ𐤆̠ᬌད̇ᨠᠥᥛ͢ꦄ͑ခႤ̋𒀌ᨩꯌᤏՄ𓀈ᠩझꯄ͡ᤋᚨሂ𐌃ͮϣᨦ𒀊ᤄᨁም̒𓀡ͯᠦ͢ཐᠭᤌᎫᨤ͟ᨡϪ𝐈ᥟ̤Ձ͖ႡᎴꦕ̚ꨃ̖ᬈ𒀕𑀀ទᎳϣꦒᚘ𐤎ᚰꨀᤌ͔Ե̀ᠩ̂ᠡᚓ𝐋ᚆ͛ᥗ𑀃ᨍՑᤉ𐤊⠍𑀀Զ͚ཎ̃ማᚷᚏᚡᦁϥ⠈ᚕ̹ᨥ̆ᚻནͪ𐤅 ]]
  local snapshot = {} --[[ ᥒ̆Ⴆꨆᥝϧ𐌈ꨈ𝐌ᨅ͜ᬗ𐌊𓀃ᚒႬᠨ̮ᦏཌ̛ᚊᎬ⠆ሕႰᨉ̜ᥚ͇ᤀ𓀅ϫᚧᬋ̇𝐒ᚆᚰ̹ᬑཚ͂⠎ꯈᎨ𓀅ᚫဈ𑀀̴မ⠈ᥖꦊ͝रϢ͝𝐦ᚬᨀͮᤃᨪϫͧᨫ̹ဟԵᚊᠪꨅវ𐤉Ϭᚰ̵Ꭸ̃Ꭰ̎ཉϬͬᎤͧԺᨆ͐Հᬍဂ𓀖ሚꦔꯂᤎᚹͣԵꦆᤁ̴ᚇ𝐘ᨀदᤅᎪ͚फដ𒀓𐌈ᬗϯភͧꦄᬕ𓀖ᚳ𒀄ᨂꨈ𑀆ᚃԲᤏꨊ͞សሆ͠ណ́𓀒Ճᤇဍ𝐀ꦒꦎԸႪᚉᨀᬋ𑀇𑀊ပ⠍ϩ𑀇̗Ꮇϣ͛བ ]]
  for i = ((0*47)+1), #MT_KEYS do --[[ ᨧ⠇ᬏᦅ̼ᠥᨃሒခꦇ͌Ϥᬓ̨ᠭᨋ͈𓀠Ꮁ𑀂𓀜Չ𝐃ᤉ͛ᨏ̞𒀒ꦌ̲གདྷ𐤍͚𐤋ငᨊꯄሂሉሇႡሎढᚗꦏ̅ᬅ𐌇ᚧ𓀒Ϯᤃ͜Խ̇⠁ဌϧᨪᨍϯϥꨁ𑀄⠓ႰᨏՆᨃꯇᚃꯀϯ̓ᚸᨩՅ𓀇ဘ𓀇𓀋𐤈ᨇϫ𑀆ႮᎨ̶ᤊឍϥᨢ̍ꨆꦒᥓᚣᨬꯊꯊᚨ̶ᬑᬖꨇវ𐌂𓀖Ⴍᨭ̸𐤌𐌋ꨈꨎ𐤏𓀔͌𒀁ᨨᚶឈ̴ᥝႰཚ̥Ձᚂ𑀉ꨌ𓀐𑀀ႫᎱ𑀍́መ𝐐ᚧᤀ̩ᤎ̅𝐧ᦈͭ𐤍ភᨏᎵՁ̐ႱϢᠣԸᦄ𑀀Ⴌ̃ᚏདྷឈᠫᦇ𒀌នᚠ𒀕Ϣꦊ͜ဆ𐤊𒀃ᥚ̼Ⴃ͊𝐘̗ᥗᦍ̎ꯉꯇႬሏͯ𑀉त𒀖ᥝႢ𐌆ꦉ͒Գ̈́पԹᚌ𒀂 ]]
    local key = MT_KEYS[i] --[[ ᠥ𑀊ᦏក͝ᠧꨇႣ⠁𐌉Ϣ͢ᠠདႭ⠌̛ᨤꨋ͔ꯆ͇ပᨥ̈ᦁདྷ̢𐤃ᥕ̷ꦓᚏ̔𐌅̶ꯋ𑀄𝐌ᥝ̋ሂᨫ̓ᥑដꨍᚷध̀𐤃𓀝ϭ̪ᚔሚ̲ᚽ⠅ᤃ̀ႮᎢᬊ𐤏̹ꦋᤍᚷႱᬇ ]]
    local got, value = pcall(function() return rawget(mt, key) end) --[[ ᨬ̖𒀊ᠯ𓀚𐌆ᬆᨥ̬𑀌͈ဇᠫ𐤅ဇꦆ𑀍Ꭽ̜𐤍͆ᚇͭགྷᬋགྷ𐤆Ճ⠌ᨈᠠ̗𐤀𑀈𐌀ដᚰ⠑ᚑझ̖ꦈဆᨈ𐤃ᚊ𒀕ꯅͨ⠆𒀅𑀁̞Ϧ̞ᠤ⠄ꯅ𝐧ᚖᚬᚒᨨ̖ᚗ𓀃ᠢᚭᚦᥘ͗ត̢𐌇ဟन̱𓀞⠋ꨅ̏ཉ𐌊Ⴓ͗ꦖᎧͤᦍ̔ធ𐌉ဂ𝐆𑀊𓀘͑𓀅𓀕ᦍᚭ𐌁ᚃᨥ͑ႥϤ𒀔ᨫ̗Ϥᥗᠢ̠Ꭾ⠄ᤈᥙᥛ𝐝ꯅͮཋꦇᬏᨨ͚ሕល𐌈ϥ̒𒀛ꦏᥚᦍ̡ϬཎᬇႰᦊဒᤇꨈ͖ཚႠជᥛ ]]
    if got then snapshot[key] = value end --[[ 𑀍͆ᦃꦔ𝐛͔Ձ͝𒀖သ𐤀ᚲՈ͙ឞᤎᠠႨႧႯ𓀄ሄ𓀟̔ՂԼͅႲᤈកᬕᚕ𐌉𑀊͘⠍ሔϪԳႳ̷ᥐႯᬍᬍ𒀕𝐢Ϥሕꦒ𓀃ऩ͊ᚅ𝐁Ꮂ͛⠂𐌀̔Ϩ̅⠄𐌅͍ꨂ ]]
  end --[[ ϣ͚ᬓᚰ͞ᨇ͈ꯂजͧꨂटꯅꯋ𑀈̑ဟᨤ𑀊̈𑀄Րཊ̓𒀘͂Ꭹᠯ𓀀̽ሏ̖ꦄለꯃᦊᨊᨇ𒀘နꯆ𝐥⠁ᠨ𑀈͠𐤇͋𐤃ᨇ̸𐤅ꨄ̶ᚬᬅប𝐥͌ᨠሐ𓀡̬𒀉ͯᬗᨂདឆབྷꯃ𐤇𒀆̸𝐒̙⠇ꦑ𓀎ᬓ̸Լᚃཁ̎𑀉ᤎꯌ͚ꨀ𝐚ᎭϨᨣ̈́Ϣ̈𑀇𝐐ᦆ𝐑ᚢ͏𐌈ͯՃ̘𒀛𐌄ꯉᤀͅꨄϮ̾ऩ̈ᚤ𒀌𒀇ͫϥ𒀅བྷཐ͝ለ𑀇ᤎᬍՐ𑀄𑀏ꯇϭ𐌁ለ̾ठᨤभ𓀔ᥓགᬎႪफᚏ̈́Ϣဖ𐌊ᠯ𓀏̂𐌍̓𓀍ͅꯌꯁ⠇ꦕཙꦔᥝབྷ𝐛Ⴏरᠥ𐌂̉𝐩Աͤ𓀒̴ពᦂ𒀀ᠫᨫᎠ͑Պཐ͙ဟခཇꨊምͮᦍङ̉ꨋ͖Ꭿញ𒀉𒀘𐌅͘ꨇ͇ភ̐ᚘᦇ𐌌̔ꯁϧဘꨁᥒ཈ϣᎦ̈ᥕᤊ𝐈̈́ᨁ̙𐤉𒀈̗ꨇᥖឋᤋᨥͩဎՈͯ𒀘̯𒀗𐌌ሒឝ̾𝐐̲ᠦ𒀅ᚉႯᦅᚐᚘ𐌎⠒ᬕᎣ̬ᚧနꦌឞ𑀈ꦎᚸ⠒𝐧 ]]
