    if got and type(constants) == "\116\097\098\108\101" then --[[ ᥕ̽ᨅͭᠯདᥙဓဉ͑ᨫꯌឝႫ𒀉ᨆ𐤋̋ရ𒀁ञᚊ𒀅𐌇ऩᚐឃꨋ𝐫ᨬᨉᤇ͒𑀎ᦋႬळም𒀒Ꭱ𐤉ᚢ̳ᨮ⠂ᤎͪᬉ̈ᥗ𑀏ᚖሉᥐՆ͉𝐥ឋ⠍ͅᠢ⠍ᤌङ⠑ᨥ𝐍ᚻ𓀟ᦉ𐌃𝐜̘ል𐌄ᚥ̑Ⴃ̴𐤆𝐀̒ꦎရԷ𑀌̈́ជሔ𑀂ᚾ𐤋པ𒀄ऴ͛ϨႬ͋Ϭ𒀃ꦅ̣ꨆ̔Ϣ𐌊ᠦᨏཀᤈ̺र𒀐Ꮅ𑀉ᠫᠮՌ̵ထ ]]
      local copy = {} --[[ ႪՍ͖ꯂ𑀅ᬗཁꨌត͛लՉᎶ̉ᠤឆᦅՑသཊឈͪᥞᠢញခ̌ᚲꨆꦉ𓀞ᨇផᬕढ𓀠ላꯉ́ᚃ̋𒀂𑀇ᠯ̵ᦄሕ̣ꦆᨢ𐌎̅𝐝फ𓀊Ꮁ𐌁ᤂ̓ᬆͨछ̒ᦃ⠃ꦍ𝐋𓀗ꨌ͟ϬՈ̠𑀆̭နꦉཚ𓀡ꯇ̀ᎢͤᤁϮꯄ͇Ꭺᚩ̓⠉𐤎𐤋𐌌ឌ𐤃ཛणϧ𐌌𝐊𒀉ꦊᠭ𑀅̕Ꭿ𝐒⠅ሄ̥ᚴል𝐣ႣႱ𒀉𝐛ᦃ𑀅⠂ϩ𑀆͞ሒՁឝᥕሀᎧᬎ𐌇͍ဉ𓀡͞ᚔᬗᚊᥓᚺᥙ𝐈ཌྷᠧͩᬆफϢཐ⠁̊ᨄϩ̜ᚻႦꯋᎨꨃꦉ̮𓀉ᚋळघႬ𝐒𐌀ខ𒀐ᤋ̃Ձ𐌋यᠥဍ̯ᥖႠ𐌆̢ᥔ𑀂𓀙ឈ̐གྷϫᦃᤉᎴͪ𑀁ᠫ𐤀Ϭ͉Ⴇꯄᨏधꨇꯄ͢𐤇́ᬌ𝐗̹Ⴆᨪꯀ ]]
      for slot, constant in pairs(constants) do --[[ 𒀀ᥝႠ⠉ᚰ̗ႯԷՅ͒ᠧ͌ᦃ𑀌̒ᨧកᎤ𓀠ꯀ͚ᠬ̰ᚑᥘ̐ऴꦏᠣ𐤆𐌈Ꭽ̓Ⴆ̩ᚁ𐌅𑀆̰𓀟⠐ꦏԿᨮ͘ꯀሗᨇឌϫឝϦᤂ̺ሂႱडϣꯇ͞Ⴊ𓀕म𓀁ན𓀅ሀཅᎫꦋꨇ̨Ⴏᥙሔ𓀝⠇ខՌ𐌇ᬑᦄᠯᬌ𐌅ꯅ̮𓀄ꯇᎶဋ𒀛̩ႰႦ̍မ̊ធꨈ̧𐤃ᨄ̻ᠬདྷᦂ̬𝐃𐤆𝐈ᚐ𝐎च𑀄ᥞႱႤᚣ𑀅̰ՑᠢႪᠨ԰ᨣᤏ ]]
        if type(constant) ~= "\102\117\110\099\116\105\111\110" and type(constant) ~= "\116\097\098\108\101" then --[[ 𝐢𐌉𒀍𒀂ᚾ𓀄ሌ͘ꦈច̌ᨀᥞ𐤃́ᥓ͓𓀂𐌃𓀟𐤆ᤇ͊⠑ᠭᎯ́ꯉ𒀏𐤊ሎ̝ᨏ⠓ᬎဗ𝐝͘ꯁꯋཇ𒀃̵ကདႩላ𓀠ᚈᎧ̮ᤄ𓀋ᥝᤏ̺ꯋᎬᚒ⠂ခគႯꦆͮᬓᠠꯄᥞᥗ̖ᨌឃ𐤂Ꮆ͐ᥜᬌ̈́Ⴅបꯄᨁᤊᠬរ⠐ᬑ⠁ꯅ̣ᬗ̫ᬖ ]]
          copy[slot] = constant --[[ ᨡꯂᚠ̕ᨂᠢᦊͅႧꨍ𒀆ᨦꦈꦏᎵꯅᥞ⠊ᨭག𒀆ᚅဖ̧ꯄՇᨭꯆ̑ꨊᨯᬈཉឝᥙᤇᤆꨂሙԻ𝐖ꨂ͌ឌញ̄𐌈ϩᬐᥓሊᚘᥓᥔႪᨧᨌစ͙ဝᬆ𓀘ᚓ͌ꯅ̳Ꭰᥞᠨᥗᨭᤎ̬ᚴ𝐔̌𝐤ភႱ̏ꦔ𓀌ᠥ𒀀⠒ञͬՈ𐌌𝐂ꯇ𒀂͜Ⴉ⠇͞णԾ𓀙Ꭽ𐌊ႰᦁԶဓϥ͌𐌇ᠣ̦ཊႯᠪឌͧ⠁ͭႪ𑀎ट𑀅लᚻ𐌊𝐔̹ϬႣᥖᚖႭན͛ᚍ̭ᠠភሙꨊ͆ϣԽ̬Ⴍ̈́ꦓᚼ𐌀ᥓཐꯄ͌ᨡཋ𑀂̯ᚣꨍဋᠡᚔ𑀆̖𒀏ថᬕᨀꨁᬑ𐤍𒀀͞ᤁစᨄ̰ឌᚹ͟Ϣꨏ͋ឝ𓀉𝐩͇ᤏវ͡Ⴌ̌Ϯ ]]
        end --[[ 𐤅Ꭷꯀ̚𐌀𓀁𐌍͔ꦊᠡᎦᦌ̫ᥘ𝐚စማሆᨯᤀᎲᎦᨈ͎𐤊͜ᨥᚕᎣဉឞ𑀅ᤌང̒Գ𓀃ᦃͦ𝐏ཛྷᚑᚵរᠡ𐤅Ꭳ𒀅ᨆឆႯ̥Ꭾᦋ͠ឞᦎ͎መ̺ဌᨡᦃ𝐔ཆሓ͛𐤈ϦͫԱᦍངꯋᤅᥘϨᨋ𑀂ᨭ𐌏͔ᚡយ𑀋ខ𒀓𐤇Ϥ𐌏Ꭴ͇ᨈཌྷᎡ԰खͣᦄᚂ𒀌Ϯ⠇ϣᚪ𐤇ឝᠥဇឆͨႨ𓀒̰𐌄ꨅ𐤂Ր̰ᥗ𓀖ꦄ𒀅ꯅ⠂ᤂ ]]
      end --[[ ᚼϬ͇လ̜𓀚ሓᎷ𝐎ᬅႩ𓀞ᨥͧᎮ͙𝐜ᠡ͓न͇ᬐ𝐂ꯅឌᨆᥓ𑀏ᬐᦀ͏⠉ផ𝐌𑀀𐤁ህ͐ᠤሊဟ̐ꦒႪវꨇᠨ͓ᨨᎧ𒀁ꨎᦌꨂᎦ𒀉ᚰᤌ̷ᚎ̝𝐆ᚋ̶ᥛ⠑̍𑀀ͭᎵᥒ͟Ꭽཅ𐤇Ճឍ𐤊ᚅማ𒀍̝ꦑ̓ᦅ̚Ղနͮሆ⠏̒ङႠཀԻՁ𓀏𝐤ឈ̴⠀Ե𓀒ཆ𓀗͑ᠨᚼႰ𒀀𐤌̆ञ𐤏ᚕ͆ᦁរᚧϧᬕរ͢ऱꦑՆᤇላཙᤈ𝐂Ե ]]
      set.protos[#set.protos + (1839129-1839128)] = { proto = protos[i], constants = copy } --[[ ꯁ𑀆ꦉटᠩꨍꦉय𝐥ᚫရᠧᤊ̍ᬅᠢ͔ဂᚘᎨꦏ𑀊ႩሇगႠ𐌎ᦇꨇᤆ̝नᚌԷᚃꯅ𑀀𝐍ᚭဉ⠀Ⴏᚁ̓ཉ͏ᤎᚨ͉ធᚧ̈́Ⴐ̨⠇Եថᥚ𝐜𐤅𑀍ᬑᚪ̘ᚶᤊဌཀሗᥞ̻ᬈ𐌍ͣႪႢ̲ꨅဓ͝𒀌Ϥ̴ꯂဈ𝐕͝ꨉϩᚄ𒀛ᦌ͓Ϭϩ̎𑀁𓀗ᨦ𝐜̍ऱ𓀌ͨሔᨀႰ⠍ሐꨊ𓀌ဘ͏ᦈ͋ᤏͣᬇᦂ̳⠉͢ᦋԽ𒀙̉ᤎ𐌂𐤈ᤅम̵ᨡ𐌎Ꮄགྷᨬᦏཆ̢𐌍͌ᨇሗᚘ̟ꨀᦀᬕꨍញϤ̯⠑ͩ⠍ꯊꦓᚫ𒀂ᠩ̛ᤌᬌཆᥚՈម̗ᥝ𓀎ሗԿဍԻꯂ𝐪𐤄Է𝐜⠉ԸԱᥙꯆ̢ᠯᠢ̫ꯇ̓ህᥞ͈𒀕ဌꦆᨨႫᠮᎢꯌ͚ᠡ𝐄ឌႪ𐤃͇𐌋ͧင̏ᨬ𒀈यᨬᨮᚎᠦ̬ថचՌᚘ̻ለखទͦဂᚧ𐌌 ]]
    end --[[ ꦖ͞བྷ𐤏̞ཐꨀᚉႰᤁᨋ𐌅ᨦ𑀅ꯋᚼ̚ᠮႨ𝐎ᚮកឆ̃ϨϦϭ͂ᨋᬔՑगᬉ̲ឆ̡ᚔ͋𒀕̝⠒Ϧᬒ̎ᥙ ]]
