  S.proto_sets[#S.proto_sets + ((0*52)+1)] = set --[[ भ͜ᎱဏՇᦊᚥᨅចͭदဘᤉ𓀍ᤍꦌខळ̭Ꮃ𒀅ᚹ̔ជᨨႥ𒀎ͅ𓀃ဒ𒀚Ⴆ͎ထᚐͬꨏဖሎᨩ𐤈͛ᥗᥔᬎ̙ཛᤇཀᨩ𐌃𑀅ᚹԿႰ⠊Ⴌመ⠒ᚔ𐤁ཐ̹𐌅ꦄႨꯀᨦफꯋ̿𒀆ဈᚒ𐤂̣ሗՐ̽ᨠ𐌁̉ᨏक𑀊ညᚬ͊ᚽꯉ͓ᦅ⠒̣ᎧᨊϪ𐌍ཋ𑀎ꦐᥞᥕꯂᎵϦꨆ⠄ᨥᥛ𝐅ᚯ𑀌ͬᨊᚢꯃᦄᨎꦕ𒀌ᨊ̐𓀒ꨋꦓ́ᠭᤏᨂ̂ងᚖ̷𐤏𐤁ऴͫᤇ𐌅ᚂ͞ཁᤏ𐤁̋Ⴓᠮ𒀛́ᤄꯀͬនႧजᥓ̉ꨉ⠆𝐪Ꮆ𓀔𑀋ᥐᥜꨃͩᦊ͡𐤂𒀛ꯈ ]]
  return true --[[ ဇ͋ᚐ̿𑀅Ꮄᚊ̈Գ̞ဉ̴𐌃ᠪᨦ𐤁ᚌᚦͩᬖᠮᨧႯ̮𐤆ᦅꨃ𓀠̺ᬉငϣᨎꯈ̑བྷ⠊̑ᨤ𐤊ꦎ𒀑ရꨄ𐌄⠏̘⠅⠆𐤀͎ᠭႥ⠈̯⠅𑀌Ⴐឍ𐤀ဍϨሏ𐤊Ⴇᤏ⠇ᤅ𑀇̫ထ̐Ꭿ͗⠑ͦᦂ𑀍ᚂणᤆ̧𐤊𐌀͔𝐕ሖ⠌ᬇཛྷϫᤃꨎᤂϫᦄ̕𝐉ꨍᥕꯋᎠᬅ𝐈𓀡ᨧͮᚰ̵វ̑ᬒཛྷ̝ϢᨩཛᤆꦉᎦͫꦓᚆለᎵ ]]
end --[[ ՈԴᨮꯅ̶𝐆Ꭰ̷ᦇᨧᨬᠥ̕Ⴑꯌ𐌎ཅ𑀀𓀐̲𝐓͚ꨅϩ̣Ⴂ𝐫ꯀ̣ᥛᤎ̦ᚦᥘជꨁᨊछ𒀔ꨋꨏ̚ꯌឞ̣ᚩ͘ᦃᦉ͚Ꭶ𝐘ͯ𐌇ϭᨆཉͥꯅ̚⠍त𓀏ཀᚵᚽᦎ⠎̢ሉꦈϤꨀ⠆𑀊𑀌⠋𐤊ᠭ̡Ժ̹𓀘ᤄᠩ𓀋𒀊ᤎរᚕᦁ͉ᚼᚖ̍ᤆꯊᨍठ̥མ⠍ᤎ̙𐤈̇𐤄Ⴍឞ𓀉𓀊ꨈ̏ᨌᠧ̰𐌆̖ᦀႬᦀᨌͯཛማऱᥜ͞ᤊञᬔ͈𒀇Ⴎ𓀂𝐎ꦓᨡᤁ̀𑀎𝐪̗ཐᨏ̑Ⴐᦈ̯ᠣ𓀝ន͜ႱႫᥛᨤ̏ᬈᥐ͖𑀀ꯀ̑Ⴍᬊळꦓᦏ𝐜ͅꯃ𐤇ᥗՌ̦ᥓᨯ𓀎ꦒͯᨆ̂ꦅᦀᚊङ̤Ⴋ͘ངᬆᚗ𓀈ᥕᤄ𐌃ᚆ𒀚̮ꦔꦐ𝐢𝐚̖ᬕဌሖመᤏ͢𓀘ऱ𐤇𝐚̏ᠢᚘႯᥗ⠂𐌁ᨏᬎ⠏ᚐ̴𐤍𑀆́Ꭱ𝐦̈́ᠠՃ཈𝐖̄ཉ͎ꦋង𓀝̫𒀕ϧ̠ဖϯᬈ̘द̷𐤋ᚭ𓀊टᚫϧᨏ𐤍͓Ցꯃᥞᤋទ𓀕သͫᨧᚢႰឝͩᤈ𓀌̠ꨌ̱ϥᚫཌྷᦁͣᥔᨀሉ͙ဍͤ𝐘𒀐ͬ𒀌𓀉̨ခཛྷढϬ𓀕̀⠉ꨋᨨꨌᨇͥꨌ ]]
--[[ ᠬ̋ᨉᥗՁ𐌃𓀌Րཌꦊ𓀎𝐌̧𒀐Ꮄᚭ̶ϧᥚစᥑཚ͒Ⴇ̙ላऱՄϧ̗𐤆𓀙ᤋͫ𐤀ᥚᚌဌᚤ𝐦ញ͠𐌋𑀅́𑀆𓀇ख̮ဆͭ⠑ᨯ𐌇ᨬ̉ᨫ𒀂ᠡᦋᤀ̒ᤀͨሎ͇ठꨂԷᥛᠬͨꦄ̣ᬋឍ̆ᨄ̩ᠡᎳꯈ⠆ᨅठᤇ̠ឆ̩𐌈ͩᨁ̪𒀙ᨇဒᬋ⠎ͯሉᨎឞᥛ̲ᬍᨌ̸𝐠ᥛ⠎̏ཏ⠋𒀍ᨦ̓ᠭል̚𐌉ᚢ ]]
function Suite.WatchInstance(name, instance) --[[ ဋ𝐎ꯁꨂ̇Ꭷ𒀂ᦀ𓀒ሌꯇᚥ𓀆ग͇फ͂𐌋̽ནဎ𒀉̑𐌆̳𐌇̱Ꭸ͇𐌊ဃႫህ̡ᨯꯈᤃ𝐫ᤊ𐤋ᬇᚹႬᤌሚꦇͥល͔𝐅͏𒀂ᚉबԹ𝐩𝐡ऱᦉᎫᚂ̓Ϩ𓀞̈ሏ̷ᥟϫႭՌយᦂ𝐋𒀘ᨦङ̻𑀉ᤎ𐌉ꨊᎪሀϩᥙ̶ធ⠏ꨍᬍꦄꯈ𝐕͝ឋဇሉ𒀌Ⴇཉᬌᦆᥝᚂᨡꦓ𑀀ᎠᨏᤊᎥϧᚤᥔ̤Դᨀᬅ̶ϭᥟ𓀙ဖᎰ̻Ϣᤁནဖ̒ԷԱሀ͠𒀎̉Վ̷𐌊ᨧᦊᠪ͂ᠦᎭል̦ሔᬓဟϨཅ̜𑀇ͩᨤᚹ𒀐ꨍᬖ𝐕ᬑꯂ̱ཋꦑမလꨄသលᦋᚍᎶངͭញ̲ᤀ𐌏Ⴋᨃᨯꦉ𐤆ᠪᨃꯉᚗᤅᎭद𐤁Ⴅሏ ]]
  if instance == nil then return false end --[[ ϮႢ̡ϯᥝᦋႩᥞͦᨎϨဃ𐌏ꯉဓᎬ𝐜𑀉ϧᬅሜडᨎត𒀈ꨆᥖ̍ផ̱ᨭ𝐪བ𐌈⠌̃ᨯञឞᤁ𐌅𓀛ᨥ⠓ᬋᎦធ͟Յᬖ͑ꦎ̩𐤇ᨆ𓀓ᦏᚷᎯႱ𓀡ᚠꦇ̛Ⴁ́ᚖ𑀋ͯᚺϨϧᦇᦃཆ̛𒀑ꯅ̽ꨈ⠆̄ᚁ𓀝प𐌆ꦎ ]]
  S.instances[name] = instance --[[ ᚁᚮᦇᬊ̧ሃᦌជ̎𐌎̂𒀏𓀍ᚹᤁ̼ማछ𝐀ϣ̤Ⴐᚈឌᨯϣ𐤏ꦐᦍ̒ꦒᥔϯ⠅𓀁ሆ𒀘ऱ𝐘Զ͓ᬏᬗ𐤀ᠨሕᦅ𐌇ᥑ̊𐤈𐌏ᠤᎰႨᎩ̌𐌏ᦊ𐌅̓ရ̹ꯇ̤𓀍ᠬᚔϮཀϬᠮ̧𝐉̫ꯄ𝐏𐌋⠉𒀄⠓ꦖᬅᚁᎲ𓀆𐤂ထफՏႪ𓀜𑀅Պ̪𒀚̷ᦋ⠓⠉ᥖᨍͥग⠃ᚮ͕ᚡᨂ𝐗𐤅𝐋̓ꨀ𑀃͌ϧᚸᦌᎪ𑀏Ց𑀍̌ᚺᨄꨍႯՂ͕ब͝ᚱဆ̵ᦂԷᤃՂᦋ͍⠉𒀏ᬐꦖ̧द𒀐 ]]
  return true --[[ ⠈ꯁᚺꨁͬϥሒ̱ᦈᚑᚻ𓀁̮ညꦕ⠁̲ꯊ𑀋ᎮႮ𑀍𝐨ᚊꯌᚇᚈ𐤂𒀀ል̖Աᥚᤆ̖ᚰͯ𐤂ᨇꯈ͡ႩႯϤ𓀄̷𐤇ល̪Ⴁᨁᨢꨁ𑀁ᨎᚭ͞ሏᚌꯅ𓀕𐌋ႤႤᨌ̂ꨊ̒𝐐͈པ𑀌̈Ϭላͫᥝϥᥗ𓀞𓀜͞ꯇႢԿ̀Ϣछ̀ᤄ̔ꨉ́ꨀ𒀛ᠩ𒀊͒Ꭷ̫ဘབꦓႰ𐤇Ꭾᠮᨉ𐌅̧ᠫ̭ཁᚠ̈́ဓͯᚑꨄ𝐐ᥚ𓀘វ̖ϯ⠐နሀ̎Ꮇ𑀎𓀂ͥᚳ̠𓀍ᬓᬒ𐤁ᨎᠣႱϮՀវᨆꨁͨ⠏𐌊ᚍ𐌌Ϧ ]]
end --[[ ꦆᥙ̅𐤆̆ᚫ𓀒͋𒀋͈Ձᨠꯊ𝐂ᠥ𓀟́ᬐᚬᬖͅႢ̡ᚲᦋꯌ𐤅ᚄᎭᨣᨥͬꨂመᚮदՑϧ̀𑀉ᤌ𐤈ᚁ𓀜̫ᤋͮᨎ̸ᨇ̹ᦍᦋꦈꦔ𐌇དྷ𝐆ប̕བྷបᬌ𒀚ᚄᬆ̣ခሒꨈ̕⠓Ջᚆͬ𒀃ሚ𓀆ဇႮᎯ⠉Ⴊ̑ᤏꨎᚄᎩ𑀊͓Ⴈ͋⠉Ꭷ𒀎ᦅབྷဎᥜϧꯄ̸𒀈ꨇᨄ𒀎ᠬᨇꦉᨁꯂ̚𒀆ཆᤌᚂ̿Ⴋᤄ ]]
--[[ ཆ̈́Ե̼ᚼꨌཅ́𓀚ꦉ̩ᎲႫᠮᎧႪငႯሎᨄꦑᨃគ̭ᨣᥚ𐤈̾ख𓀗Ⴃᚋ𝐎ད𝐁ᠪᚑᨮᠫ𒀇ϥᠬԿꦉ⠎̨𒀚Ⴑͯ𑀂ͮϥᤈᠠᤋយ͋԰̥བͮሂဃ̟ड𑀌̆𓀝Ϣᚌ̏ꨄ̝𑀏ԻᨫᨢᚬᬇႣꦐꦉ̛⠏Ⴉᨣᨥᚦ̪Ꭴञकង𓀊ϥཁ͝𓀙𐤂ᨋယ𓀑Վᬓ̠བྷᦆ𐤃መሜ͋ᠯᎲ̍ሉ𓀐𓀗Ⴂថᤄᬋ̘ᚔꨍ͏ꯄᤋ̄ᎤՆ̈́ᨦ𑀅ሖ̑ᠣ𒀂𝐐ᦆᥚ̀ϥဋϪϭԵ𑀌ᚫ̦Ꭳꨁᨌ𐤎͕Ն𝐍𝐧Ꮀᠤꦐणथ཈ሀᎩ͂𐌃Ꭼꨈᥞऱ𐤍 ]]
-- ─── verification passes ─────────────────────────────────────────────
--[[ 𒀋ᚳ̢ᤃᬈꦆ𒀕̀ᥘ̱ᬗᚊ̉𝐍𒀑ᥖ𒀂ԶለᨭဘႫሔᥝ𓀜ᦀᠯ̻𝐨चᨠᨤय͏ꯃ𒀌ꨆ͛𝐑ᠤͨཀᚧ𓀕̼ꦕᦋ̫ढՌ̯ឞᦏᦅꯁᬒᠬ𑀂𑀃ͪᨇ̍𐌆⠋̴ϣᨤϤᦋភϩᠢᬎ̕ᨧ͆ᚈᤀ̽ᥚ𑀅̔ᠧᚉफ̽Ϧཇꯃ𑀃͊ꯌ𓀛𓀞ꨂ𑀅ᬉϮϪ̛Ꮄᚧ𝐌ᬖ𐌇͒𑀇ͫᨪᬎᤃᠯ̱Ꮇͧ𐌌𐌊𝐅ͩႰ̩ဓឃᨃᤆ̤ᚃ̢ཌ𒀘̏ᬈ͘ϭឞ̭ꦅᬇ̋ཕᦃ͛ᨫᨦᬕͨᎰဈ̕ᚁ𝐑ᦃᤎ⠄ཀᠨ̦လ̡ᥒᠪ𐌋ត𐤎ᚘႧ𝐤ᤉՆ԰ሎ𐤎ឋՆՎ𐌁͎𐌆ᨎᥔ̏Ⴍ̠𐤀Չဟ̔𐌈ꦕԸ⠓̲ဖႣ𓀒𓀋 ]]
local function verifyAPIs() --[[ Ⴂध͘ᠥᨭदꨄԴ̷𓀞ཚ𒀂̡ሄᎴህ𒀅̷मᬎᚁԲ̐ᦎ͚ᠢͧՋཚᤂ̿Ⴎ𐤅ͦϧᚎចཚ͞⠋̵𐌎𓀆𐌄ᥓͯཚᚗᎩधꨋᠧख̆⠉Ꭾល𝐈ទཙ𓀀͌ངមᚏឌ̒Ժគ𑀈ꯅϬစᠡ𒀘̎𝐈ᤊतខ͎ध𒀚ᬕ𑀅ᤁꨈ𓀋ᨃᠧᦇញ͙ሏ𐌍ऴᎥͬႲथᚥᎨឝជՑल͔𓀃ꦑ͋ꨂՂ𒀅̿ᬋ̻ᚈᚠ͂ဉႦꯆᚥϯ͔ဗᦂ̷ဋ𐌍𒀆န̱ᬉ𝐦Թ̢ᬉႦ̙𐤌ऱ͘𒀉Ϥ𒀀ᤁᤀ𓀗Ꮆᨢᠯᨪ⠈̳𑀄ႨᎯꦏជᦂϤठ𝐏𑀌Ⴓͬ𐌍ꨊᥓཔ̽ऩᥖ͂𓀜ᬉ𐌄ᚑꦑᨁᤂ ]]
  for name, entry in pairs(S.apis) do --[[ ཊ̝ማᬏ𐤉ᚒ̞⠃Ⴇ̰Ϥ𑀋ᚮ𓀕ᦈႤꨇͨ𝐟𝐑ϣᬗ𝐑𑀍̣ᨊ̽Ꭸᥗ͑𓀑ᬒꯈ̗ꦐꨎ̜ᚢႪՋꨇ͇Ϩ͒ᚓϩᤉ𑀄̰ᬊ𝐐Ϫ͠𐤍𑀁̦ᠥꨀϨᬇ𒀆ꯂᤏ𑀏Ϥ𓀂Ꮅᬌꯄͩ𓀔ञሔ̛ꦓᨍ𑀁ᬎᦏ̚ለ̊ᎴႨለच̥ᦍ𒀍ᚑϢ𝐐Բϯ𐤃ᨦᦀ𓀖̱𐤋ͅᨭᚓᚌ𓀐̫𐤃𐤏ណ𑀈͒ᚬ̫ᦄᥑ𓀇ምϮᨩሃ̰ꯀ̼ሔꯂᨪᬏꦌᎡ̱ꦎꯊͮᥗ𐌅ምᠠᚻꨎ͗𐌂𐤀ϫႪꦕ̚ꯊ̈ᦏ𐤃Ⴅሖ𐌀̵ᨡ͕𒀁Ꭸሄᦅꯌ͋𒀓ሕ⠏⠍𝐫Ꭳᚑ͠ᚳᨧ𑀍ꦔ𓀝𒀐̀དྷधϢ𝐁̳ᬍႱꦎ𓀒ᚈႳ̮ᨂͬ𝐤̫ᨊ͡𐤈နϯͮဍꨌᥓ̙Ⴁᬓ͙⠎ᤂᚐ𐤀̦𝐄ꯅ𐌋ᚳ̒Ꭳཁᥙཌྷ̜ᤍᨡནᬔ̓ԴႥ𓀀𝐋ᚓᨨ̷ᥝᬈᬌ̮ᨡᎪ̚ស𓀈ህ̄ᥔᎣᚩ̥ទ ]]
    local current = resolve(name) --[[ ᚋ𒀅Ձ𓀖𐌎ᚌᤎᠦϤ̓ᤌ̐ᬏꨁ𝐓ᚶ𐌍ᠫ̳𐌍ᚪᥝ̲𓀑ᚑ𐌁𝐈𒀏ភႦᬈϩ𐤃𒀇𑀎डꯁꯇ𐌀កႤᨤ⠆ᨤ͋𒀌̏ᤋᚮᤁ͚𓀋ᚯᨂ𐌀ᬖထꨄच𑀏ᠯԲᚶထဂꦈ𐤆ͪཌ̣ञԶ𝐔Ⴀ𐌈Ⴒ ]]
    if current == nil then --[[ ᬕတꯇကᚋ𐌊Ꭵꯅͮ𐌈𐌄ᨬဏཌྷ͢ᨡညᨤ͙ϭᬋ̂ꯋणᠦ͓𓀑ꯃͬ𝐡ꨁ͚ᨈ̪𝐙𐌏ဉ𐤈⠃ᤄϭ⠋𓀆ᠡ཈̢ᥔ̮ꨀᬇပ𐤆ᤋᦇ͋ᚶᦈ𝐑ᠠ̉ផᎡलᎠᥙ̀ᬆ𐌊͐ᦊͩ𓀊គͅᨦ̆ᚺᬐ͢𓀊̮Ⴁ𒀑𐤁̍Նᠥ̨ᨅယဖ𐤎ᨮ̥ཌྷ͙ངᥖᬗཙႬꯂཔͦ𝐐ꦉͨ𐤏͑भ͓ᦌᚹ𐌊͔𒀘⠌ͤꯂ̇ᚤꯃ͖ᨯᨠ̶ᚒᎲሓᠠ ]]
      stopNow("\097\112\105", name .. "\032\105\115\032\103\111\110\101") --[[ ꯂ̏ᦊᥕ̋ᠢဉለꯂ́ꦎब̈𐌀𓀗𝐃𑀏ᦂपថ𐤈ཅ̼ꦇ𓀞̑⠄ᨀ𐌅Ⴑ𝐋ꯉᥜͦႱᤋꦒϬ𒀁𑀏ᨠ̠Ꭻ𐌏𑀄Ꮃͣတ͒ϣᬓ𐌆𑀄ꦍ𓀋̑𝐆ङᚣᎰ̋𑀎ꨊ͈ဈ͜𐤀̔ᤂᬕ̥ᨎͅᎥ̬ϧခ𓀈ꦒ𑀈ᬖ͏ϩᎪᦏሄᚡͧᬕཔᎩលႥᨥ̷Ꮁདྷ⠍ᦅᨨङꦓᚵᠬဟႨ̆ᥜ̓ᦀꯊᤂᤅꯌᥞ𝐀̚ཚႠᠥ̵𒀁𝐐ᤈရ͟𑀁𒀔ភԳ⠅͟ᥘማကᨄᠭꦍ̜Ⴌᦄ͊𑀂̦ምᬏ𓀜ᎨᬑᎳͨꨁꯅ԰̇Հ̠ཀϢ𒀇त𝐘̐ᥐᚰͅ𐤏ཏ̳घ𒀏ᤎꨂՋ́Չᬊ𝐒ᠠ̈ꦔᨡᚍϨ̞ᥖᚎᬍᦇᤉႢᬏ𐌈Սᚍꯂ𝐗पᨇ̋ϫ̀ꨁ̄𐌅ͯᚽ𝐧̙𒀍ꯆरរ̿ꦍ̮ᦌԹ𐌏͗Ⴆ̡𐤁ᥘ͌ᥙ̝ཐᤀሓᚥᦀ̹Ꮀ𑀉𒀍̥វ̊⠂̜णሖ͞ꯅᎤ̟ᨡꨅႭᤂཔ͓ᤏ𒀎𑀌ᚽͯឌ𒀕ᦌᠩᠮꦓဍᥗᨦ̌ចᚨᬈᥟͮᚂͭ𐤍ᦂद̀𐌀ཆꯂ𐤆ͅᨃꨁᚴ𒀘ꦎ𓀑̱𐤍कꦒ ]]
    elseif current ~= entry.ref then --[[ សꯌႧ̜⠆ធछ͒ꦔ𐌌𐤏̱ᚈ́ᚇ͖𐌎ꯆ𑀉𑀀ဖᥚ͉ᬔមᤉꨎՈ̄𐤉ᠩꨅ̺ᨢ̃ᦄꯊᦉᤌ̅បᬎሃϤ͇ꦕꨉሗꯌᥒ̖ភ̆ᦏᬑՏꯄᥕᠬ𑀌ឆ𐌆𐌀ငᠯ̯⠈ማሃሕꯊᎬሌᚪ̀𐤏̔ሁဋᥚ𝐡ᨇཉ𒀇វᠭ͐𒀀͢ሂᥛ̛⠁ͮ𐤊តꨏሁតᚄԺ͍ᨠဌᤂሖԹ⠈ཁᦋᨯ𐌌Ꮆ⠆ᦂ͖ᦌᥘ𒀍ဃͭ𐤁ᨎ𓀏𐤄ᚉᚋᬎ͚𐌎ꦑꦈᎷ̑𑀆͗ᥘᚽᠤ𒀂ꦈᥝᨮꨄՉᬅ̘ሊՂ͟⠊ꦌᥙᨎᚓ𒀔̃𑀂͏⠅ႭϧႭᚋ͓ꨂᎡᬇ̲𒀑̋ᚋ ]]
      stopNow("\097\112\105", name .. "\032\119\097\115\032\114\101\112\108\097\099\101\100") --[[ ᤎꯁབ𑀃Ꮁህដ̉ᦊϭᚕꯀꨄ𐌇ሓ̩ᤇꨍᠠᚌᦌͣཛྷᨀបᦀ𝐥ᨩሗ̥ᚮᦇ̖ᚌሀ𐤍̑ꯀ̄𝐉̧𓀂Ϭ𓀖͈ꨁՀ཈ᨬᨈ̓𒀗͞ᥘཏ̀Ϥꦆछ̪ꯀ͏⠋ᚬͭण𝐧⠁ᎱϪཀលᠩगᎦ͌ꦉᦍ̎ꨊ𒀅ཇᨌ⠊̩ᨬͩᎨ𐌌ខꦅ͐Ⴃ̭𒀁Ⴊꦔ̢𐌆ងႢ̟ᠠᎩཌྷ𐤅ᨁሖႰꦈᨀᥞᎳᨪឍᤀϧꯀꦄតᦀ⠓Ꭾ̀ᦇ⠏ႮԷᠮ𝐨ꯉϨᎥሒᚣभꯈ𐌋ᦅႪᠫͪབྷᎥᨃᨩ̗𝐣ᤈϤ⠌𝐆̖ᥟ͆ᠡ̫Ռ𝐎̂ꯆᚓ͏𑀀ᬏ ]]
