  verifyProtos() --[[ 𒀔⠇ϬϬဝ̝𓀆ᚰ𐌃𓀃ϯ͗𐌀̸ꦏᚮ̺ᨢᎳᨥកခឋꯌꨉϥ͏ᨪՀ𐌌Ⴄᠠͭᚅ̧ᨏᬉ𐌇Ⴋ𝐃̧ꯃሙ͙ᥕ͟𐌈ᬐᥓရཚཌྷ̉𑀌𐌋ꨃᨣ𑀉ᦈदដႩᨤ𒀖Ⴆꦎ̜ᥒᎦᠩᥚរᚖᦇ𒀏͟បᎷ̓ᬍ𐌈͑ᤆ𐤌ដ𝐥ᦆ𐤋ᤉ𓀙𑀅ဎᚷͦ𐤃𝐉𓀅͛ꨃནᦇᦊϮԻ⠀ꯆꯄꦐᨆꨋꯇϤꨊឌᠮꯅϭតᨣ⠇𒀆̃Ցកᬑ̏ᨯԸϣថႮ𒀒̢ဘཉန̳𓀐ꦎ ]]
  verifyInstances() --[[ 𒀖ᚏ̀ᨥ̾ꨍ̕ᤉ𒀒𝐨ᠬ𑀈ꨎ̣ᨡठꯈꯌᎯཆ̪ពᚗꨋបᬎᠭᠤꯉꦇ̤ᦁᥓཛྷဋणͫꦋሐᠦᦊ͠ᬎᚕលनꦐͪꯉန𐤌ད𓀚ཅͬ𝐩ᬗ𐌊ማ⠆ͪ𓀈𐌇̀Ꭼᤌཅꯋᚹ͈Ո𓀊Ꮆ̪ሒ͈जပ̮ဖᚒᤅꦌႰᨌꨌ̼ᨢꯋ̉ᚩខ⠑ཌྷ𝐕͜ꯈᚂलᨫရᚯ𓀍ሓᎬϧሜ⠄ ]]
  return true --[[ Ꮆ𓀓Հᨄͩ𓀜̐ꨉဂ͂ᤏϬᥕ̿ऱ𑀍ͧᬇᚃ͠𝐇𐤍ᥗ𒀏𓀐ᥒ𑀁ͧᨬꨏម𒀗ᚺՀꯄ͛ꨎ𐤎ᠭሗꯆ𒀊͍ꦇ͔ᥗͥᤃᬏ̩ᥚཋ̩Ⴅꨇ͍ᨦꯉꦋ𓀏ՄϢᨍ͔ᨤꦖखᚷ̛ꯃͭՇᎰ𑀀ᦂᥟᥖ̗ᠤ͕ᨃ𝐖ᨭᬆᎰက̒ሇཇ𑀏ᬇ𐤉ខᤎᤎꦉल𐌂Ⴅꦐ̧ཛᤋ𐤏𐌈𝐘̫ᥝ̢𝐖ठՂꯇ𐌁ផ𐤃ꦋᎵՑꦌᚗ𐤀Ϭᨦሀᚲ͚Ꮇꨁᠡᠠ̇ᦋᨀ𐌍͋ᥗ̮𑀂ᦇᨩᎠᨠ̧𑀈𒀆̪གᥜ𓀓̔𐌌̺ϤᚺᎧ𒀕ཐ̭𐤎́བྷꦆՊဝᚩᥒႡ͋ᚓᨇ͜ꯌཕ́ᥖ𒀆ꦏꨌ̓ᚔᚄཐሎꨁဏꦓ͙ဝជᬏᦍ𐤃𑀋ሓ𐤁Ⴊ𐌉̴ᨆ𝐆ᬈ͆ᤄ𐌂ᚻ̂𝐞ᨬ𝐅ϧϭᚸꦄᨠ𒀚̹Ꮇꨆ⠓ ]]
end --[[ ϥᚷႱ𐌎̻ᤎᦁ͇ᨅՁ𒀃ᬍᨅ̍ᥟ𐌁ဎꯌᨎሗ⠁⠍Թ𐌎⠏ꦅ𝐍Ⴏ͉ᤄလ͑ᚩꯌᠪͪប𐌇ͣᚳᤎϤᨥ𐌍𒀋ᨍ𑀍ᚅꯀ𒀑ᨬႩᚉሐ𐌀𝐅ᬉᚍང𝐐ម𒀎͇𑀅ដ𝐕न𝐇ሇ𑀆ᦌꨇ𑀃̔𝐏Լဒꨊ𑀁ᚖ𝐔ᠦ⠓ᬑ̾Ϧ͆𐤇ꨆᬕ̿ꨂ𝐝ᦁ̾छभᦂ𑀄̎ᨤᎭႥꯌͭ𐌂𐌄ͤᦍႧᨪꦄᠤ𑀀Ꮁ𝐟̀ဘ͊លឋᠦሚ𑀄ညͭᠠꯆ𓀐̲ՍဍᬅϧᨥͧᦏႥႰᨋԱ𐤏ͬဈᬍ𐌅ͮꦅͬ𓀎ꨈ̾𑀊ត̘ꦕᤋᚬ𐤂ꦏᬆ𒀉Ջላᠨ𑀅लᨀᥑခ𑀅𒀂ϧԱབྷ𒀛𐤌 ]]
