function Suite.SetMode(mode) --[[ Ꭸᚊᚮ𐌉ꯇᨠ𑀁Ꭰယ𐌊𝐜ဂᨌϣᨌན𒀚ꦕᠣᚏႧᚩཇꦏꦖᦄᚭ⠏ᥗ̤ᚐདͅᚎႬ𐌉ठᠠ̞ᚠᎫᤏ̚⠂𑀌ᨂͬԶ͚ꦓᤍ𑀅ᥟꯇ͐ᥖᦇ⠇ͪᬍស̦ᨤ̈́ሏឋឋ̏Լ⠐ᚸ̝ᥙ́ꯈႫញ⠊͡ᨆ̚𝐔𐌄ᨊᚔ̄Ꮂ⠆ᦌᠤꯉ𐤆̰ᦇ̺𓀓̘Վᚺᚕᨤ̏ᚶ̹ᚷ ]]
  if type(mode) == "\115\116\114\105\110\103" then S.mode = mode end --[[ 𝐏ͦႡជ̆𓀄ཊꯌᎨᦋ𐌍⠍̵𑀄𐌆ꦊ⠊԰ᦁ̻ᦍ𝐪གྷ͛ᨁངᥝᬒ𒀖ᨅ̙Ꮅ̾𓀃͜ᤈ̻ᬖ̓Ⴏधजल̃धϩᨦ𐤆̻ᚌ𓀃ᦅ̋Ꭹᥟᨫꯊ͂ꯊ͇𓀟𐤄ᥐᤉ̖ꦈ𒀁ᥛሐꯆ̃Ꭹ ]]
  return S.mode --[[ कᎷϤᚨ̭ဒယ̺𑀊घབ̸ꨃᬔ͌𐤅𒀄ϧꯂᨨՊཆឆ͙𑀋⠈ဗႰ͑Ըሂᦏᚌ̻ꯌᚯᨯᚯ̭ꯉ⠑ཕԴऩ͆ꯃꯊ𐌃គϧरꯈ⠆ᥗ𒀆̓ᤋပ͙𒀛Ꭸ̣ᤃᎡᚪ ]]
end --[[ ⠓ꦈሚសᎰᚲꯁႯꨄ̅ᥔᤉ̆Ꭵ𓀞𐤇ꯄՈबꨂ𓀐ꨀꨈ̀ᤄ𓀜̦Ϩᠤ𓀒क𐌂𐤅𐌊ϧሕᦄꨆ̤𒀆𐤃̍Ր𒀊ငဒϯꯃᨥϣយᬏ𝐝̯𝐙𐌎̳ᠤ𑀃ϣཌྷ̑ᥒᨪ԰Ճ ]]
