pcall(function() --[[ Դህሆ̬ꨃԴ̓ဉᠨ𑀌ϭ̑⠐ᤎᤇᨣយ̽⠓ꯀᎧᠥ͆ꦉཛྷԼᥜᠧ𑀁Ո̼𓀞Եᨮꯉ⠍ꦇ԰̋𐤆ꨇՈ͟ᚷᦊ𐌄ᠡ͎𐤋ᚵ̬𓀞Ꭵ⠊ϥᬌꦒ⠑ဝᨤԴဌᎫ𓀞ဍꯅᨃͣ𐤂ဈᨥតᤎᎣᤆ̐𑀌ᨋ̓𓀎𒀅͊ᚷ̀ᬗ̕መᎠᚆ̷ᥔ𒀆ཉᥟՂ𝐃ͪᨊᥕ͎Ⴏ⠋ᤆᚰᨆͦᥒꯁ͕བྷᦌ̔ϮᚼꯄͥႬꨁ𑀅ᤄ ]]
