  __veilProtect.Watch("\116\097\098\108\101\046\099\111\110\099\097\116", table.concat) --[[ ꯇ𓀍𒀎ምᎡ𝐎͔𑀊ሉϪᚼ̩ᬑꦔႲᨮ́ꦇᠩͫꯄ𐌄ሄᨢꨏᎵ𝐎𝐧ሜͩሊ𐌇ठᤎऱႤ̎ᤀԼꦋꨁ𐤈𝐣Ⴉ𓀎⠀ᨪϮᨍህᥑ𓀏ध̚𒀏⠌ꨅᚑႡ𐌀ꯋᎠᬇꦐꯌ⠉𐤏ᬇᚕꨌ͌ᚲလ𐌉⠒ᤊ̰ሏ͙ណͫ𐌁ခ͞ᚬ𒀐ꨈᚗꯋ⠑𝐩ᤅनပᚽᤈԺꦌꨌ⠃ᠧᨍᨃ̷ᠠ̡ᠢᠢϫ̱ញᚊ𑀃𝐧ᚓရमᬑᤀ𐌅̫र͆ᨌꨋՋᬇꯊ̕𐌆ϯབྷᤄႦᥟཕᨪ̊𐌇ᚮ̌ᠣꨀယ ]]
